quests[28407] = { id = 28407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Junggesellin", description = "Feuerbart? Meine Schwester heiraten?! Ich schwöre Euch, die Welt ist verrückt geworden, {name}!\n\nAber vielleicht hat Kurdran Recht. Eine nette, ganz normale Hochzeit würde alle auf andere Gedanken bringen... und Feuerbart ein wenig abkühlen. Es hat mir eigentlich ganz schön Spaß gemacht, hier mit ihm gegen die Oger zu kämpfen.\n\nAlso gut! Fanny hat das letzte Wort. Irgendetwas sagt mir, dass sie sich nicht gern binden lassen möchte.\n\nFliegt zurück nach Kirthafen und fragt sie, ob sie einverstanden ist. Ich werde unsere schmutzige Aufgabe mit den Ogern hier erledigen.", sourceObjective = "Sprecht mit Fanny in Kirthafen im Schattenhochland.", completion = "<Fanny wirft verärgert die Arme in die Luft.>\n\nIhr, Kurdran, Feuerbart und jetzt auch noch mein Bruder. Anscheinend ist bei allen das Hochzeitsfieber ausgebrochen!\n\nGut, dann heirate ich Keegan Feuerbart eben. Aber nur weil er stark und gutaussehend ist und einen Kiefer hat, der Steine zerbeißen kann, und einen Hintern so hart wie ein Amboss. Nicht aus politischen Gründen.\n\nAber wir werden Eure Hilfe brauchen. Wir haben eine Mordshochzeit auszurichten und nicht viel Zeit dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[28408] = { id = 28408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Geballtes", description = "Traditionell tragen die Bräute der Wildhämmer weiß als Symbol ihrer Reinheit. Zusätzlich tragen sie eine Krone aus schwarzen Federn, um ihren geballten Mumm zu zeigen.\n\nAm besten zeigt man seinen Mumm mit Eulenfedern, und Fanny verdient nur das Beste. Im Hochland leben viele Waldeulen. Sie kreisen meist um die Bäume an den Klippen. Nehmt Euch ihre Federn.\n\nAm besten tötet ihr sie vorher.", sourceObjective = "Sammelt 12 makellose Eulenfedern.", progress = "Habt Ihr Fannys Federn?", completion = "Ah, Ihr arbeitet schnell. Eine geballte Ladung Federn für eine geballte Ladung Frau. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28409] = { id = 28409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Gebrautes", description = "Eine Wildhammerhochzeit ohne standesgemäße Getränke wäre eine Beleidigung. Kurdran selbst hat ein paar Fässer des seltenen Donnerbräu Lagerbiers aus Hochstade angefordert, aber die Karawane konnte den Pass nicht überqueren.\n\nFolgt der Straße östlich von hier, die um die Südseite des Bergs Donnerschlag führt, und holt die Karawane ein. Sucht nach einem Kerl namens Hammerhand und helft ihm, das Gebräu über den Pass zu bringen!", sourceObjective = "Sprecht mit Hammerhand auf der Straße östlich von Kirthafen und begleitet die Versorgungskarawane sicher in die Stadt.", completion = "Ah, Russell der Barde schwärmt immer von Donnerbräu Lagerbier. Es hat sicher nicht den Kick eines guten Wildhammerbräus, aber er hört gar nicht auf von seinem \"Körper\" und den \"Geschmacksnuancen\" zu reden. Schätze, wir werden es herausfinden, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[28410] = { id = 28410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Gestohlenes", description = "Für solch ein Ereignis will jeder natürlich besonders gut aussehen, aber feiner Zwirn ist im Hochland rar.\n\nSoweit ich weiß, benutzen jedoch diese verdammten Goblins an der Küste feinste Seide, um die Ballons ihrer Zeppeline zu reparieren. Was für eine Verschwendung!\n\nFindet einen Zeppelin, der zwischen dem Hafen des Drachenmals und den Krazzwerken hin und her fliegt, und stibitzt ein wenig Seide aus dem Frachtraum in den unteren Decks.", sourceObjective = "Sammelt einen Ballen feinen dunklen Stoffs.", progress = "Wie lief der Raubzug in den Lüften?", completion = "Oh, genau! Kilts für die Herren, Roben für die Brautjungfern.\n\nSagt den Damen bloß nicht, dass sie Kleider tragen, die für ein Luftschiff gefertigt wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28411] = { id = 28411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Geschmortes", description = "Und schließlich brauchen wir noch ein Festmahl. Und bestimmt nicht solche modernen \"Häppchen\". Diese Menge will Fleisch und zwar viel davon.\n\nSammelt Wildbret von den Hochlandelchen und Hochlandrehen. Die Hochlandworgs sind auch ganz lecker. Bringt mir ein paar Rippchen. Wir werden Euch einen Schmaus auftischen, wie Ihr ihn in den ganzen Östlichen Königreichen noch nie gesehen habt, Freund.", sourceObjective = "Sammelt 8 Scheiben frisches Wildbret und 5 Worgrippchen.", progress = "Was gibt es Neues von der Nahrungsfront, {name}?", completion = "Da schau mal einer an! Ihr biegt Euch ja richtig unter dem Gewicht des ganzen Fleischs. Dann schicke ich meine Leute lieber mal an die Töpfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28412] = { id = 28412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haussegen" }
quests[28413] = { id = 28413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Text und Musik von...", description = "Ich habe in meinem Leben schon viele epische Melodien verfasst, {name}, aber diese nahende Hochzeit verdient eine ganz besondere Ballade. Und das schnell!\n\nSoll ich eine Ode an die Liebe schreiben? Eine scherzhafte Melodei? Ein anzügliches Trinklied?\n\nIch könnte ein wenig Hilfe mit dem Text brauchen, wenn Ihr Lust habt, Euch als Schreiber zu versuchen.\n\nSprecht mit mir, dann schreiben wir zusammen ein Lied!", sourceObjective = "Sprecht mit Russell Brower und helft ihm, ein Lied zu schreiben.", completion = "Ein echter Ohrwurm, so viel ist sicher.\n\nAber ist es auch ein Klassiker?", sourceObjectiveStatus = "unverified-source-field" }
quests[28414] = { id = 28414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drölfmeterschießen", description = "Jetzt liegt es an Euch, <Junge/Mädel>. Ihr habt die Dampfdruckhaie vernichtet, also müsst Ihr jetzt nur noch das Siegertor schießen.\n\n<Der Trainer beugt sich zu Euch hinüber und flüstert Euch ins Ohr.>\n\nNur unter uns... Ich finde, wir müssen jetzt aufs Ganze gehen. Ich möchte nicht, dass Ihr einfach nur ein Tor schießt... Ich möchte, dass Ihr so weit schießt, dass die Fußbombe zwischen den beiden Schornsteinen hinter dem Ziel hindurch fliegt!\n\nIch habe die Fußbombe ein wenig verändert, sodass sie die zusätzliche Leistung hat, die Ihr benötigt.\n\nUnd jetzt geht raus da und macht mich stolz!", sourceObjective = "Steigt in den Bilgewasserbukanier und schießt das Siegertor, indem Ihr die Fußbombe durch die beiden Schornsteine hinter dem gegnerischen Tor schießt.", completion = "Äh... Ihr habt es geschafft, Junge. Ihr habt es WIRKLICH geschafft! Wir haben das Spiel gewonnen und...\n\nHABT IHR DIESEN DRACHEN GESEHEN?!", sourceObjectiveStatus = "unverified-source-field" }
quests[28415] = { id = 28415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieben auf einen Streich", description = "Wir müssen handeln. Winky und Gor'tesh hatten sich gestritten, also habe ich diese Freundschaftszeremonie geplant, damit sie sich wieder versöhnen. Alles lief super, bis...\n\nNun, den Rest kennt Ihr ja.\n\nIch habe sogar Getränke besorgt!\n\nWinky liebt Flammenfliegen. Er schleicht sich fast jede Nacht davon, um sie zu jagen. Vielleicht ist er ja dorthin gegangen.\n\nIhr findet die Flammenfliegen im Westen und Norden, immer in der Nähe von Lava. Bringt mir sieben davon. Beeilt Euch!\n\nGor'tesh geht vielleicht als Nächster!", sourceObjective = "Sammelt 7 Feuerfliegen.", progress = "<Oralius schnappt in die Luft, hebt seine Faust und späht hoffnungsvoll zwischen seinen geschlossenen Fingern hindurch.>", completion = "Ihr werdet nie glauben, was passiert ist! Winky ist zurück! Wir haben gar keine Feuerfliegen gebraucht.\n\nBekommt ein {race} hier vielleicht einen Bauchkrauler zur Feier des Tages? Kommt schon! KRAULT MEIN BÄUCHLEIN!", sourceObjectiveStatus = "unverified-source-field" }
quests[28416] = { id = 28416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Rache", description = "{name}... seid Ihr das? Ich dachte, Ihr wärt tot, so wie der Rest!\n\nNein, Ihr wart schon immer stark. Schon damals im Rotkammgebirge.\n\nUnser Kampf ist noch nicht vorbei, {name}. Sie haben schon einmal unsere Heimat angegriffen. Ich bin hier, um sicherzustellen, dass das nicht noch einmal passiert.\n\nWenn Ihr immer noch so kämpfen könnt wie damals, dann schließt Euch mir an. Geht zunächst nach Süden in die Schlupfhügel und tötet ihre Jungdrachenbändiger und Schwarzdrachenbrutlinge.\n\nEs wird wie in alten Zeiten sein.", sourceObjective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", completion = "Ich bin froh, Euch an meiner Seite zu wissen, {name}. Die Kompanie Bravo wieder vereint, was?\n\nOh, habe ich erwähnt, dass Trottmann auch hier ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[28417] = { id = 28417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unschuldig", description = "Die Schwarzfelsorcs in der Steppe dienen einem finsteren Meister, der abartige Experimente an lebenden Wesen durchführt, um seine eigene Menagerie der Monstrositäten zu schaffen. Viele seiner Testobjekte sind so verderbt wie ihr Meister, aber ein paar davon sind vollkommen unschuldig.\n\nIn den Schlupfhügeln im Süden ketten sie Jungdrachen am Boden fest, um sie für solche Experimente vorzubereiten. Das lasse ich nicht zu. Zerbrecht ihre Fesseln und bringt die Brutlinge zu mir... in Sicherheit.", sourceObjective = "Beschafft einen befreiten roten Welpling, einen befreiten grünen Welpling, einen befreiten blauen Welpling und einen befreiten bronzefarbenen Welpling.", progress = "Ich hoffe, wir kommen nicht zu spät.", completion = "Ich werde mich darum kümmern, dass diese Drachen versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28418] = { id = 28418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Rache", description = "Ich bin von Geburt an ein Schwarzfelsorc. Ich habe einen Großteil meiner Kindheit in diesem Berg verbracht.\n\n<Ariok zeigt auf den Schwarzfels im Norden.>\n\nAber auch wenn das gleiche Blut in unseren Adern fließt, teile ich ihre Ansichten nicht. Ich suche nach einem Verbündeten, der mir dabei hilft, ihren kommenden Angriff aufzuhalten.\n\nAlso beweist Euch. Reist nach Süden in die Schlupfhügel und tötet ihre Jungdrachenbändiger und Schwarzdrachenbrutlinge. Zeigt mir, dass Ihr für diesen Krieg bereit seid.", sourceObjective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", completion = "Ihr seid also dabei?\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[28419] = { id = 28419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstockung", description = "Wenn wir einen Krieg gegen den Schwarzfelsklan führen wollen, müssen wir vorausplanen. Mein Vater hat bereits einen Plan geschmiedet - jetzt wird es Zeit, ihn in die Tat umzusetzen.\n\nIch brauche Skorpidstachel... die schärfsten, die Ihr finden könnt. Skorpide befinden sich überall in der Steppe, aber die meisten befinden sich in der Schlucht im Westen.\n\nZerbrecht Euch nicht den Kopf darüber, wofür sie sind. Das werdet Ihr noch früh genug herausfinden.", sourceObjective = "Besorgt 5 rasiermesserscharfe Skorpidstachel.", progress = "Schon zurück?", completion = "Man kann diese Skorpide leicht unterschätzen. Ihr habt Glück, dass Ihr nicht an einem dieser Stachel steckt. Oder vielleicht seid Ihr einfach nur gut.\n\nIch füge sie dem Vorratslager hinzu. Wir sind noch nicht fertig, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28420] = { id = 28420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zukünftiges Projekt", description = "Laut meinem Vater brauchen wir Worgbälge, und zwar viele. Es macht nichts, wenn sie zerrissen, versengt oder blutig sind. Hauptsache es sind genügend.\n\nEigentlich wäre es sogar besser, wenn sie ein wenig ramponiert aussehen.\n\nWorgs findet Ihr im Westen und im Osten.", sourceObjective = "Besorgt 11 Glutworgbälge.", progress = "Dann schauen wir uns die Bälge mal an.", completion = "Glaubt mir, {name}... Ich kann es genauso wenig wie Ihr abwarten, bis wir endlich zum Töten kommen. Aber wir müssen uns an den Plan halten. Das Jüngste Gericht kommt früh genug.\n\nIch werde diese Bälge hier aufbewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28421] = { id = 28421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammschlacht", description = "Ich hoffe, Ihr habt keine Angst davor, Euch schmutzig zu machen. Aber wenn ich Euch so ansehe, dürfte das kein Problem sein.\n\nIm Norden am Rand der Lava findet Ihr dunkle Schlammhaufen. Den Schlamm brauche ich.\n\nAm besten stellt Ihr keine Fragen und konzentriert Eure Bemühungen darauf, Befehle zu befolgen, {name}.", sourceObjective = "Besorgt 9 Haufen obsidiandurchsetzten Schlamm.", progress = "Ihr solltet Euch vor den Obsidianelementaren hüten. Sie schleichen sich gerne an.", completion = "Genau das brauchen wir.\n\nKeine Sorge, {name}... Eure Klinge wird bald Blut zu schmecken bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28422] = { id = 28422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sand, der Apfelwein und die Kugel", description = "Mein Vater wartet auf uns im Osten. Bevor wir aufbrechen müssen wir jedoch noch ein paar Vorräte sammeln. Diesmal werdet Ihr es einem Hexenmeister mit Namen Gorzeeki Wildaug abnehmen.\n\nWahrscheinlich findet Ihr ihn im Nordwesten in der Nähe des Altars der Stürme. Sagt ihm, dass er uns helfen wird. Wir brauchen den Sand, den Apfelwein und die Kugel.\n\nEr weiß schon, was das bedeutet.", sourceObjective = "Sprecht mit Gorzeeki Wildaug in der Nähe des Altars der Stürme.", completion = "Bah! Wer seid Ihr?\n\nOh, also hat Ariok Euch geschickt? Gut. Würde es Euch etwas ausmachen, wenn Ihr eine Weile hier bleibt? Nichts Großes... Ihr müsst nur ein paar Hexenmeister für mich töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28423] = { id = 28423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenmeister haben das beste Zeug", description = "Ariok sagt, er braucht Vorräte? Ich habe haufenweise Vorräte! Das Problem ist nur, dass diese Hexenmeister mich aus meinem Zuhause geworfen haben und mich nicht wieder hineinlassen.\n\n<Gorzeeki mustert Euch.>\n\nIhr könntet vielleicht hineingelangen. Geht nach Norden und holt mir meinen Schlummersand, mein Teufelskarussellstöffsche und eine klare Glaskugel. Ich bin mir ziemlich sicher, dass es das ist, was er haben will.\n\nOh, und falls Ihr aus Versehen ein paar dieser Orcs tötet, während Ihr da oben seid, wäre ich bestimmt nicht traurig.", sourceObjective = "Besorgt eine Handvoll Schlummersand, einen Krug Teufelskarussellstöffsche und eine lupenreine Glaskugel.", progress = "Mal sehen, ob Ihr alles bekommen habt.", completion = "Ich hoffe, dass ist das, wonach Ariok gesucht hat. Im Moment kann ich jedenfalls nicht viel damit anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28424] = { id = 28424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenboxen", description = "Ner'gosh der Schatten ist der Anführer dieser Hexenmeister, die sich nördlich von uns befinden. Er ist der Fiesling, der mich aus meinem Haus vertrieben hat, als diese Schwarzfelsorcs aufgetaucht sind. Nun, eigentlich sind sie alle Fieslinge, aber er ist der fieseste.\n\nWenn ich jemals in die Nähe des Altars zurückkehren möchte, muss Ner'gosh verschwinden.", sourceObjective = "Tötet Ner'gosh den Schatten.", completion = "So wie ich diese Orcs kenne, wird bald ein anderer seinen Platz einnehmen. Ich werde versuchen, mich zurück in den Altar zu schleichen, bevor das passiert.\n\nHabt Dank, mein Bester.", sourceObjectiveStatus = "unverified-source-field" }
quests[28425] = { id = 28425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Ariok", description = "Ich schätze, ich bin hier mit Euch fertig. Ich werde diese anderen Orcs davonscheuchen, sobald ich den Mut dazu gefunden habe.\n\nHier, vergesst Eure Vorräte nicht.", sourceObjective = "Bringt die Hexenmeisterausrüstung zu Ariok am Flammensternposten in der Brennenden Steppe.", progress = "Sieht aus, als wärt Ihr mit Gorzeeki gut zurecht gekommen.", completion = "<Ariok wirft einen Blick in die Kiste.>\n\nGut, gut, gut. Wir können weiter. Unser Krieg führt uns nach Osten, weg vom Schwarzfels... fürs Erste.", sourceObjectiveStatus = "unverified-source-field" }
quests[28426] = { id = 28426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meißelgriff, das Herz der Steppe", description = "Wir sind auf dem Weg nach Meißelgriff, das sich genau im Herzen dieser Steppe befindet. Wir treffen uns dort mit der Thoriumbruderschaft und mit meinem Vater.\n\nSeid Ihr mit der Bruderschaft vertraut? Diese Dunkeleisenzwerge haben mir mehr als einmal geholfen. Wir brauchen ihre Hilfe vielleicht erneut.\n\nWir kommen auf unserem Weg dorthin durch den Schwarzzahnunterschlupf. Was haltet Ihr davon, wenn wir unterwegs ein paar Orcs töten? Ich werde in diesem Lager langsam ein wenig unruhig.", sourceObjective = "Tötet 15 beliebige Schwarzfelstruppen auf Eurem Weg nach Meißelgriff.", completion = "Ihr müsst mich entschuldigen, aber wir empfangen derzeit keine Besucher. Ich bitte Euch, Meißelgriff auf demselben Weg wieder zu verlassen, den Ihr gekommen seid.\n\nOh, Ariok... Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[28427] = { id = 28427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nadel im Höllhaufen", description = "Lok'tar, {class}. Mein Name ist Etrigg vom Argentumkreuzzug... ehemals Ehrenwache des Kriegshäuptlings. Und davor Schwarzfelsorc.\n\nIch nehme an, mein Sohn hat Euch in unseren Plan eingeweiht. Hat er nicht? Nun, es ist vermutlich besser so.\n\nDer nächste Teil des Plans erfordert ein wenig Feingefühl. Sprecht mit Thelaron Düsternadel, dem Schneider hier vor Ort. Ich habe ihm bereits die Bälge und den Schlamm gegeben, die Ihr gesammelt habt. Er muss Eure Maße nehmen.\n\nGenau, {race}: Wir werden Euch als einen der Feinde verkleiden.", sourceObjective = "Sprecht mit Thelaron Düsternadel in Meißelgriff in der Brennenden Steppe.", completion = "Ihr braucht eine Verkleidung? Nun, da seid Ihr genau am richtigen Ort, Schätzchen.\n\nLasst mich mal sehen... mm-hmm. Ich weiß genau, was wir machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28428] = { id = 28428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als einen Orc verkleiden. Ihre Armee besteht hauptsächlich aus Orcs, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Ausrüstung vom Tisch des Schneiders zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung? Mein Vertrauen in unsere Chancen schmilzt.\n\nAber ich habe trotzdem noch Vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28429] = { id = 28429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Oger verkleiden. Die Oger der Feuermägen haben immer für die Schwarzfelsorcs gearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Ausrüstung vom Tisch des Schneiders zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung? Mein Vertrauen in unsere Chancen schmilzt.\n\nAber ich habe trotzdem noch Vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28430] = { id = 28430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Goblin verkleiden. Die Schwarzfelsorcs haben schon immer goblinische Söldner angeheuert, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Ausrüstung vom Tisch des Schneiders zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung? Mein Vertrauen in unsere Chancen schmilzt.\n\nAber ich habe trotzdem noch Vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28431] = { id = 28431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Troll verkleiden. Die Gluthauertrolle haben stets mit den Schwarzfelsorcs zusammengearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Ausrüstung vom Tisch des Schneiders zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung? Mein Vertrauen in unsere Chancen schmilzt.\n\nAber ich habe trotzdem noch Vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28432] = { id = 28432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schwarzzahnunterschlupf", description = "Bei verdeckten Ermittlungen geht es eigentlich fast nur um Wichtigtuerei. Verhaltet Euch einfach, als hättet Ihr alles Recht der Welt, dort zu sein und es wird schon klappen.\n\nEure Kontaktperson im Schwarzzahnunterschlupf ist ein Orc namens Rüstmeister Kaoshin. Er weiß NICHT Bescheid, dass Ihr ein Spion seid, also haltet Euch bedeckt. Tut, was immer er von Euch verlangt.\n\n<Etrigg drückt Euch ein kleines, mechanisches Objekt in die Hand.>\n\nSteckt Euch dieses Gerät ins Ohr. Ich werde mit Euch in Kontakt bleiben und spezielle Anweisungen geben.\n\nViel Glück da draußen, <Soldat/Soldatin>.", sourceObjective = "Sprecht mit Rüstmeister Kaoshin im Schwarzzahnunterschlupf in der Brennenden Steppe.\n\nBereitgestellter Gegenstand:", completion = "Wo bleibt Ihr denn, Grunzer? Ihr seid spät dran! Gebt mir auch nur einen Grund, warum ich Euch nicht auf der Stelle einen Kopf kürzer machen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[28433] = { id = 28433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grunzertreiberei", description = "Pah! Ihr habt Glück, dass mir heute die Arbeitskräfte fehlen. Sonst hätte ich Euch für diese Woche zu <meinem Prügelknaben/meinem Prügelmädchen> gemacht.\n\nDie Stiefel der Offiziere und hochrangigen Soldaten müssen gewienert werden. Sie stehen draußen vor ihren Hütten.\n\nIch möchte mich darin spiegeln können, Grunzer! An die Arbeit!", sourceObjective = "Poliert 7 Paar Schwarzfelsstiefel sehr gründlich.", completion = "Hmpf. Gute Arbeit, Grunzer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28434] = { id = 28434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personaleinsparungen", description = "<Ihr hört ein Summen in Eurem Ohr.>\n\n{name}? Ich bin es, Etrigg.\n\nWir haben gerade die letzte Information für Eure nächste Mission erhalten. Es gibt drei Ziele, die ihr für uns aus dem Weg schaffen müsst. Das erste ist Voodooist Timan, den Ihr auf der Aschensäule findet. Worgmeisterin Othana hält sich in den mittleren Worgzwingern auf. Und Gorlop findet Ihr in der Nähe der Lavabecken im Süden.\n\nIn Eurem Gepäck werdet Ihr die Skorpidstachel finden, die Ihr gesammelt habt. Wendet die Stachel zur richtigen Zeit auf die Zielpersonen an.", sourceObjective = "Benutzt den rasiermesserscharfen Skorpidstachel, um Voodooist Timan auf der Aschensäule, Worgmeisterin Othana in den Worgzwingern und Gorlop bei den Lavateichen auszuschalten.", completion = "Ihr habt nicht nur alle Anschläge vollbracht, sondern sie auch alle wie Unfälle aussehen lassen!\n\nIhr wart wirklich der richtige {race} für diese Geheimmission. Gut gemacht, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[28435] = { id = 28435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Kodorufers", description = "Nun gut, ich habe richtige, ehrliche und sogar wichtige Arbeit für Euch! Wir müssen die Kodos rufen, die in den Gebieten südlich von hier grasen. General Thorg'izog sagt, dass wir bald ins Rotkammgebirge aufbrechen, und ich kann nicht zulassen, dass wir ohne die Kodos aufbrechen.\n\nBenutzt dieses Horn in der Nähe eines Kodos. Sobald es den Ruf hört, wird es sich auf in Richtung Lager machen.\n\nIhr müsst aber aufpassen. Manchmal sind die Kodos ein bisschen angriffslustig, und es kann sein, dass Ihr ein bisschen mit ihnen 'spielen' müsst, bevor sie auf Euch hören.", sourceObjective = "Benutzt das Horn der Rufer, um 7 Kriegskodos des Schwarzfels zurück zum Lager zu rufen. Bekämpft feindselige Kodos, bis sie aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28436] = { id = 28436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir behalten das Horn", description = "{name}, Etrigg hier. Ich will, dass Ihr dieses Horn behaltet. Ich bin sicher, dass wir improvisieren können, um es in unseren Plan einzubinden.\n\nIch bin etwas besorgt über das, was Kaoshin zum Angriff auf das Rotkammgebirge gesagt hat. Wir wussten, dass ein neuer Angriff aussteht, aber nicht schon so bald!\n\nKehrt mit dem Horn zu mir zurück. Wir werden hier in Meißelgriff weitersprechen. Versucht, Eure Verkleidung nicht zu verlieren. Ihr seid mit Eurer verdeckten Arbeit noch nicht fertig.", sourceObjective = "Bringt das Horn der Rufer zurück zu Etrigg in Meißelgriff in der Brennenden Steppe.", progress = "Willkommen zurück, Soldat.", completion = "Ein Angriff auf das Rotkammgebirge ist zwar auch ein Angriff auf die Allianz... aber es ist auch ein Angriff auf Unschuldige.\n\nDas lasse ich nicht zu. Nicht als Kreuzfahrer. Nicht als Orc.\n\nEs ist Zeit, dem Schwarzfelsklan, meinem alten Klan, beizubringen, dass die Tage ihrer Raubzüge gezählt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28437] = { id = 28437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Thorg'izog", description = "Kaoshin hat sich als hilfreicher herausgestellt, als wir vermutet hatten, aber jetzt brauchen wir ihn nicht mehr. Es ist an der Zeit, mit dem General zu sprechen. Ich glaube, Ihr seid bereit.\n\nGeneral Thorg'izog ist einer der \"großen Drei\", die die Bodentruppen in der Brennenden Steppe anführen. Er befindet sich in der Schwarzfelsfestung im Nordwesten. Zieht Eure Verkleidung an und sprecht mit ihm. Versucht, sein Vertrauen zu gewinnen. Ich werde mich bei Euch melden, sollte ich noch etwas von Euch brauchen.", sourceObjective = "Sprecht mit General Thorg'izog.", completion = "Noch mehr Außenstehende? Was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[28438] = { id = 28438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmataufe", description = "Ich muss aus dieser Situation das Beste machen. Diese Goblinsöldner haben mir diesen riesigen Feuerelementar als \"Dankeschön\" geschickt, weil ich sie angeheuert habe. Was soll ich denn hier in der Steppe mit einem Elementar anfangen? Das ist ja fast, wie Wasser zum Meer zu tragen.\n\nWenn Ihr nach Arbeit sucht, so könnt Ihr Euch nun beweisen. Sprecht mit diesem Goblin hier und fordert seinen Elementar zum Kampf heraus. Ich werde dem Sieger meinen Respekt zollen und meine Zeit geben.", sourceObjective = "Sprecht mit Würtl Sprillhuper und bittet ihn, Magmalord Kolob freizulassen. Besiegt danach Magmalord Kolob im Kampf.", progress = "Was ist los? Habt Ihr Angst?", completion = "Ich hatte fast damit gerechnet, dass Ihr als Sieger hervortreten würdet. Mir gefällt Eure Art, zweifellos.", sourceObjectiveStatus = "unverified-source-field" }
quests[28439] = { id = 28439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin das Gesetz und dessen starker Arm", description = "Ich war auf der Suche nach <einem starken Soldaten/einer starken Soldatin> wie Euch. Ich brauche jemanden, der dafür sorgt, dass meine Truppen sich benehmen.\n\nAußerhalb der Festung bereiten sich die Orcs, Oger und Trolle auf einen Angriff auf das Rotkammgebirge vor. Meine Unteroffiziere halten sie zwar auf Trab, aber sie brauchen Hilfe.\n\nNehmt diesen Knüppel und diszipliniert ein paar meiner Soldaten.\n\nEs ist mir egal, ob sie in Reih und Glied stehen oder sich fehlverhalten - ich will nur, dass sie eine Tracht Prügel bekommen. Ich will, dass sie sich konzentrieren, auf die Schlacht vorbereitet und abgehärtet sind, und gefolgsam.\n\nGeht nun.", sourceObjective = "Benutzt den Disziplinarknüppel des Schwarzfels bei 20 Einheiten in den Feldern der Ehre. Wenn jemand merkt, wer Ihr seid, so erschlagt ihn, bevor er Eure Maskierung aufheben kann.", completion = "Ich habe das Gefühl, dass wir von Euch noch viel hören werden, Soldat. Ich freue mich darauf, an Eurer Seite im Rotkammgebirge zu kämpfen.\n\nWegtreten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28440] = { id = 28440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtmissbrauch", description = "{name}? Etrigg hier.\n\nWie es scheint, habt Ihr Thorg'izogs Vertrauen gewonnen, denn er hat Euch für die Disziplinierung eingeteilt. Das ist ein Glück.\n\nWir müssen diese Feldwebel loswerden. Ihr findet sie außerhalb der Schwarzfelsfestung in den Feldern der Ehre auf Wölfen reitend. Benutzt den Knüppel so oft wie nötig, bis sie sterben. Ihr müsst schnell handeln, denn wenn sie merken, dass Ihr <keiner/keine> von ihnen seid, dann werden sie versuchen, Eure Maskierung aufzuheben. Seid schnell und zügellos, {name}.", sourceObjective = "Tötet 5 Feldwebel des Schwarzfels mit dem Disziplinarknüppel des Schwarzfels. Besiegt sie schnell, bevor sie Eure Maskierung aufheben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28441] = { id = 28441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug Schaden für einen Tag", description = "Wir haben keine weitere strategische Verwendung für Thorg'izog oder die Bodentruppen des Schwarzfels. Wir müssen nun die nächste Phase des Plans einläuten.\n\nWenn Ihr bei der Festung fertig seid, kehrt zurück zu mir und meinem Sohn in Meißelgriff.", sourceObjective = "Kehrt zu Etrigg in Meißelgriff zurück.", completion = "Seid Ihr wohlauf?\n\nGut. Ihr habt dort draußen Stärke bewiesen, {name}. Stärke und Weisheit.\n\nUnd nun packt Eure Sachen zusammen. Wir ziehen weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[28442] = { id = 28442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenkamm", description = "Unsere Arbeit hier in Meißelgriff ist getan. Das verdanken wir vor allem Euch. Wir werden jetzt weiter nach Nordosten ziehen, zum Flammenkamm.\n\nDer Flammenkamm liegt in den Klippen, hinter den Ruinen von Thaurissan. Dieser Ort sollte ein geeigneter Ausgangspunkt für den letzten Teil unseres Plans sein.\n\nNatürlich reist mein Sohn Ariok mit Euch. Und ich ebenso.", sourceObjective = "Meldet Euch bei Kibler auf dem Flammenkamm in der Brennenden Steppe.", completion = "Oh. Besucher?", sourceObjectiveStatus = "unverified-source-field" }
quests[28443] = { id = 28443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschwärzte Asche", description = "Ihr müsst für mich noch etwas besorgen, bevor wir uns dem Rest der Schwarzfelsarmee annehmen können. Wenn wir das hier tun wollen, sollten wir es richtig tun, und das bedeutet, dass wir uns vorbereiten müssen.\n\nIch brauche Asche, {name}. Nicht irgendwelche Asche... Asche von den großen Obsidianelementaren, die sich in den Ebenen im Südosten aufhalten. Das Zeug ist tiefschwarz, und genau das brauchen wir für unsere nächste Verkleidung.\n\nKeine Sorge, Ihr habt schon eine Verkleidung. Diese ist für jemanden... naja, für ETWAS... anderes.", sourceObjective = "Sammelt 9 Haufen Obsidianasche.", progress = "Die Asche der Obsidianelementare ist besonders dunkel - und genau, was wir für unser Vorhaben benötigen.", completion = "Ja, die sind gut genug. Ich werde sie für Euch schön einpacken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28444] = { id = 28444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Dämonen des Landes", description = "Die Lavaseen südlich von hier sind die Heimat der Flammkin, eine besondere Art Feuerdämonen, die die Steppe schon lange beheimaten. In der Schwarzfelsarmee sieht es so aus, als könnten wir - wenn wir vorsichtig genug sind - ein paar der Flammkin hinter die feindlichen Linien schmuggeln, um für Verwüstung zu sorgen.\n\nBringt mir die Leichen von mehreren Flammkin. Als Dämonen kann man sie leicht wiederbeleben, und dann für seine eigenen Zwecke einsetzen.", sourceObjective = "Sammelt 18 gefallene Flammkin.", progress = "Die Flammkin sind schwach, aber sie reisen in Rudeln. Seid vorsichtig.", completion = "Für das ungeübte Auge sehen sie aus wie Wichtel.\n\nWir müssen sie nur diesem eben ungeübten Auge unterjubeln. Ich werde sie jetzt für den Einsatz vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28445] = { id = 28445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein köstlicher Haufen Worg", description = "Wir brauchen frisches Fleisch und deshalb werdet Ihr Euch auf die Worgjagd machen. Die Worgs auf dieser Seite der Steppe sollten die sein, auf die Ihr Euch bei der Jagd konzentriert.\n\n<Etrigg holt eine große Klinge hervor und händigt sie Euch aus.>\n\nMacht Jagd auf die riesigen Glutworgs. Benutzt diese Säge, um die besten Fleischstücke aus den frisch getöteten Worgs zu schneiden. Worgs sind überall in der Steppe zu finden; südöstlich von hier ist gleich das erste Rudel.", sourceObjective = "Benutzt die Worgsäge, um aus den frisch getöteten riesigen Glutworgs 40 Worgschnitzel zu schneiden.", progress = "Glück bei der Jagd gehabt?", completion = "Das Fleisch sieht gut aus... aber ich glaube, wir müssen es noch ein bisschen \"würzen\". Ich werde sicherstellen, dass sich jemand darum kümmert.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28446] = { id = 28446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutrunde", description = "Meine Beine werden schon wieder ein wenig rastlos. Habt Ihr Lust, eine kleine Runde zu drehen, {name}?\n\nWir werden uns auf eine Reise um den Schreckensfels begeben. Ich möchte die Schwarzfelsarmee erst ein wenig unter die Lupe nehmen, bevor wir zuschlagen. Da dachte ich mir, wir könnten auch ein paar von ihnen töten, wenn wir schon auf dem Weg sind.", sourceObjective = "Tötet 25 schwarze Großdrachenbrut oder Schwarzwyrmkin.", completion = "<Ariok trieft vor Blut und Schweiß.>\n\nGenau das hatte ich im Sinn!", sourceObjectiveStatus = "unverified-source-field" }
quests[28447] = { id = 28447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenvorhut", description = "Die Schwarzfelsorcs kommen nicht allein. Die Oger der Feuermägen und Trolle der Gluthauer, die an ihrer Seite kämpfen, habt Ihr bereits gesehen. Leider haben sie aber auch die schwarzen Großdrachen auf ihrer Seite.\n\nDie Orcs und Drachen haben bereits ihre Champions zu Sammelpunkten geschickt, um Wache zu stehen. Ihr könnt sie an den Drachenschädeln auf Piken erkennen, die herumstehen. Wir beide werden diese Sammelpunkte finden und die Vorposten ausschalten, bevor die Schlacht beginnt.\n\nSeid Ihr bereit?", sourceObjective = "Tötet Minyoth, Welpenbändigerin Akumi, Terromath den Versengten und Tugnar Blutschlund.", progress = "Kommt schon, {name}, es sind noch ein paar von ihnen übrig. Unsere Arbeit ist noch nicht erledigt.", completion = "Ihr werdet immer besser, {name}! Jetzt fallen sie, so wie wir es wollten.\n\nUnd wir werden siegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28448] = { id = 28448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Handel mit einem Drachen", description = "Auf unserer Reise um den Schreckensfels gibt es noch einen Zwischenstopp.\n\nErinnert Ihr Euch noch an die Brutlinge, die Ihr aus den Schlupfhügeln befreit habt? Ich habe mich um sie gekümmert. Jetzt werden wir sie zu jemandem bringen, der besser für sie sorgen kann als wir. Er hält sich am Schlitterfels auf, nordöstlich des Schreckensfels.\n\nSein Name ist Acride. Er ist vielleicht der Schlüssel zum Sieg in der bevorstehenden Schlacht.", sourceObjective = "Bringt die geretteten Welplinge zu Acride im Schlitterfels in der Brennenden Steppe.", progress = "Da seid Ihr ja, {name}.", completion = "Ja, die Welplinge. Ich werde mich um sie kümmern.\n\nUnd was die Vereinbarung angeht, die ich zuvor mit Eurem Vater getroffen habe, sagt ihm, dass ich meinen Teil des Handels erfüllen werde. Ich werde Euch Euren Drachen für die Schlacht gegen die Orcs schicken.\n\nWir hegen beide einen Groll gegen den Schwarzfelsklan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28449] = { id = 28449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstellung der Bauern", description = "<Ihr hört ein Summen in Eurem Ohr.>\n\n{name}. Ihr und Ariok scheint Eure Aufgaben erledigt zu haben. Ich bin ebenfalls mit meiner fertig.\n\nKehrt zum Flammenkamm zurück. Ich habe ein paar Pakete für die großen Drei vorbereitet: Thorg'izog, Neeralak und Xi'lun. General Thorg'izog habt Ihr ja schon getroffen. Jetzt habt Ihr die Gelegenheit, auch den anderen beiden zu begegnen.\n\nBevor Ihr sie tötet, meine ich natürlich.", sourceObjective = "Kehrt zu Etrigg auf dem Flammenkamm in der Brennenden Steppe zurück.", completion = "Gut, Ihr seid zurück.\n\nIch hoffe, Ihr habt die Verkleidung noch. Ihr werdet Euch wieder mitten unter die Feinde begeben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28450] = { id = 28450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Thorg'izog", description = "General Thorg'izog ist bei den Ogern im Ofen der Feuermägen, eine Höhle in der Westwand des Schreckensfels. Bringt diese Lieferung zu ihm und den Ogern.\n\nDarin befinden sich die Worgschnitzel, die Ihr besorgt habt. Sie wurden in dem Teufelskarussellstöffsche mariniert, das wir vom Altar der Stürme erhalten haben.\n\nIhr solltet nichts davon essen, wenn es Euch irgendwie möglich ist.\n\nBringt die Schnitzel zu General Thorg'izog. Er wird sich darum kümmern, dass seine Streitmächte Essen im Magen haben und mit ein bisschen Glück isst er auch etwas davon.", sourceObjective = "Tragt Eure Schwarzfelsverkleidung und bringt die in Karussellstöffsche marinierten Schnitzel zu General Thorg'izog im Ofen der Feuermägen in der Brennenden Steppe. Sprecht mit Etrigg, wenn Ihr eine neue Schwarzfelsverkleidung braucht.", progress = "Was habt Ihr da, Soldat?", completion = "Nun seht Euch das an! Jetzt weiß ich, wer mein Lieblingssoldat ist!\n\nIch werde die Schnitzel unter den Ogern verteilen.\n\nIch werde Euch am Rotkamm wieder sehen, Soldat. Für die Ehre des Schwarzfels!", sourceObjectiveStatus = "unverified-source-field" }
quests[28451] = { id = 28451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Neeralak", description = "Die Hexenmeister des Schwarzfelsklans üben ihre Magie oft in der Schädelhöhle östlich des Schreckensfels. Ihr Anführer Xi'lun ist gerade andernorts beschäftigt, sodass die Höhle derzeit von einem anderen der großen Drei beaufsichtigt wird: Drachenlord Neeralak. Neeralaks Fachgebiet sind Drachen, nicht die Totenbeschwörung.\n\nIch habe die Flammkin, die Ihr gefangen habt, mit dem Schlummersand bestreut. Überzeugt Neeralak davon, dass es sich dabei um Hexenmeisterwichtel handelt, nicht um Flammkin. Wenn sie aufwachen, werden sie alles andere als glücklich sein.", sourceObjective = "Legt Eure Schwarzfelsverkleidung an, schleicht Euch in die Schädelhöhle und überzeugt Drachenlord Neeralak, Eure Kiste voller schlafender Flammkin anzunehmen. Sprecht mit Etrigg, wenn Ihr eine neue Schwarzfelsverkleidung benötigt.", progress = "Was?", completion = "Was soll das sein? Aha, das sind also Wichtel?\n\nIch bin mir sicher, dass Wichtel nicht einfach so in Kisten schlafen!\n\nAber ich nehme Euch beim Wort. Ich verstehe nichts von diesem Hexenmeisterquatsch. Stellt sie in der Ecke ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[28452] = { id = 28452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Xi'lun", description = "Man hat uns berichtet, dass der oberste Hexenmeister Xi'lun, das letzte Mitglied der großen Drei, sich in einer Höhle auf dem Gipfel des Schreckensfels aufhält und seinen großen Augenblick vorbereitet.\n\nEr erwartet eine Lieferung: eine Kugel der Herrschaft, mit der er ein mächtiges Beschwörungsritual durchführen kann. Ich möchte, dass Ihr ihm das hier gebt.\n\n<Etrigg reicht Euch eine Glaskugel.>\n\nDies ist die klare Glaskugel, die Ihr aus dem Altar der Stürme befreit habt. Sie ist machtlos. Gebt sie Xi'lun und betet, dass er den Unterschied nicht bemerkt.", sourceObjective = "Legt Eure Schwarzfelsverkleidung an und bringt die klare Glaskugel zum obersten Hexenmeister Xi'lun auf dem Schreckensfels in der Brennenden Steppe. Sprecht mit Etrigg, wenn Ihr eine neue Schwarzfelsverkleidung benötigt.", progress = "Ich habe keine Zeit für Spielchen, Narr. Geht mir aus den Augen.", completion = "Pff! Ihr seid spät dran! Wisst Ihr, wie lange ich schon warte, dass Ner'gosh mir endlich diese Kugel bringt?\n\n<Xi'lun schaut auf die Kugel, dann wieder zu Euch.>\n\nEtwas ist merkwürdig an dieser Kugel... Sie ist zu...\n\n<Xi'lun verstummt.>\n\nAch, schon gut. Meine Nerven liegen wohl einfach blank. Vielen Dank für die Lieferung. Für Blut und Donner!", sourceObjectiveStatus = "unverified-source-field" }
quests[28453] = { id = 28453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geladen und entsichert", description = "{name}, bitte melden. Könnt Ihr mich hören?\n\nDie Schlacht beginnt gleich. Ich hoffe, Ihr habt alle Pakete ausgeliefert.\n\nIch brauche Euch hier auf dem Flammenkamm, SOFORT.", sourceObjective = "Meldet Euch bei Etrigg auf dem Flammenkamm in der Brennenden Steppe.", completion = "{name} ist da! Wir können loslegen.\n\nDas ist der Moment, auf den wir gewartet haben, {name}. Ich hoffe, Ihr seid vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[28454] = { id = 28454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Schreckensfels", description = "Das ist es also, {name}! Ein trauriger Tag... aber ein Tag, an dem die Schwarzfelsorcs eine wichtige Lektion lernen. Heute setzen wir unseren Plan in die Tat um.\n\nKommt mit mir. Wir werden mit Acride sprechen und den Gefallen einfordern, den er uns schuldet. Dann werden wir die Invasion im Rotkammgebirge aufhalten, bevor sie überhaupt begonnen hat.", sourceObjective = "Tötet 200 Eindringlinge des Schwarzfels. Wenn Ihr Euer Fahrzeug verlieren solltet, benutzt das Horn der Rufer, um es herbeizurufen.", completion = "<Etrigg blickt auf die Zerstörung unter ihm hinab.>\n\nUnsere Aufgabe ist fast erledigt, {name}. Es ist Zeit, ihnen den Todesstoß zu versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28455] = { id = 28455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhm im Chaos", description = "Ihr und mein Sohn geht zurück zu diesem Berg. Drei Orcs haben den Angriff überlebt, und wir geben keine Ruhe, bis sie den Tod gefunden haben.\n\nGenau, ich spreche von den großen Drei.\n\nGeneral Thorg'izog ist in den Ofen der Feuermägen gekrochen und Drachenlord Neeralak hat sich in der Höhle auf dem Berggipfel verschanzt. Xi'lun hält sich im hinteren Teil der Schädelhöhle auf und schmiedet Pläne mit seinen Hexenmeisterfreunden.\n\nMacht Euch einen Namen, {name}. Besiegt diese verderbten Schwarzfelsorcs ein für alle Mal.", sourceObjective = "Tötet General Thorg'izog, Drachenlord Neeralak und oberster Hexenmeister Xi'lun.", progress = "Viel Glück, Bruder.", completion = "<Etrigg verneigt sich.>\n\nWillkommen daheim, Jungs.", sourceObjectiveStatus = "unverified-source-field" }
quests[28456] = { id = 28456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsbeute", description = "Die Schwarzfelsorcs schwirren zwar immer noch in ihrem Turm herum, aber ich bezweifle, dass ihre Pläne sie in nächster Zeit auch nur in die Nähe der Unschuldigen im Rotkammgebirge führen. Das habt Ihr und Ariok ihnen sicher ausgetrieben.\n\nIch muss sagen, dass wir hier in der Brennenden Steppe nicht mit Einfallsreichtum gegeizt haben. Diese Hexenmeisterausrüstung, die wir gesammelt haben, war äußerst praktisch, und auch die Obsidianasche, mit der wir unseren Drachen versteckt haben, war ein cleverer Schachzug.\n\nWir haben jedoch noch ein paar Gegenstände übrig. Bitte, sucht Euch etwas aus, bevor Ihr die Steppe wieder verlasst und weiterzieht.", sourceObjective = "Untersucht die Kiste mit übriggebliebenen Vorräten auf dem Flammenkamm in der Brennenden Steppe.", completion = "Ihr schaut hinein und findet...", sourceObjectiveStatus = "unverified-source-field" }
quests[28457] = { id = 28457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefährliches Bündnis", description = "Die Zerschmetterte Hand glaubt, dass die Dunkeleisenzwerge und der Schattenhammer zusammenarbeiten. Es gibt Beweise, dass sie im Schwarzfels einen gemeinsamen Angriff planen. Wir können nicht zulassen, dass eine solche Armee aus dem Schwarzfels marschiert.\n\nIhr müsst in die Schwarzfelstiefen reisen und die Angriffspläne des Schattenhammers von General Zornesschmied in der Westgarnison beschaffen. Beseitigt die Elementare, die der Schattenhammer zur Unterstützung der Truppen bereitgestellt hat.", sourceObjective = "Tötet 6 Brandwachenzerstörer und beschafft Euch die Angriffspläne des Generals von General Zornesschmied in der Westgarnison der Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28458] = { id = 28458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zauberfoliant des Pyromanten", description = "Tief im Schwarzfels wächst die Macht der Dunkeleisenzwerge und ihrer Schattenhammerverbündeten. Pyromant Weisenkorn ist ein mächtiger und angesehener Magus in der Gesandtschaft des Schattenhammers. Wenn wir seinen Zauberfolianten in die Finger bekämen, könnte ich mir vielleicht Gegenzauber für die Flüche und Zauber des Schattenhammers ausdenken.\n\nIhr müsst in die Schwarzfelstiefen hinabsteigen, den Schrein von Thaurissan ausfindig machen und den Zauberfolianten besorgen. Zeigt Weisenkorn und seinen Zwielichtdienern keine Gnade!", sourceObjective = "Tötet 6 Zwielichtabgesandte und besorgt Weisenkorns Zauberfoliant von Pyromant Weisenkorn am Schrein von Thaurissan in den Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28459] = { id = 28459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Bindung", description = "Die Zerschmetterte Hand hat von einer verstärkten Zusammenarbeit zwischen dem Schattenhammer und den Dunkeleisenzwerge in den Schwarzfelstiefen erfahren. Wir haben die Möglichkeit, unserem Feind einen Schlag zu versetzen und unsere eigene Macht zu stärken, {name}.\n\nDie Anhänger des Schattenhammers haben mehrere Steine der Elementarbindung in der Schattenschmiede, dem Domizil, dem Schrein von Thaurissan, der Westgarnison und der Ostgarnison aufgestellt. Findet und holt Euch diese Steine!", sourceObjective = "Besorgt 6 Steine der Elementarbindung aus den Schwarzfelstiefen. Ihr findet die Steine in der Schattenschmiede, dem Domizil, am Schrein von Thaurissan, in der Ostgarnison und in der Westgarnison.", progress = "Konntet Ihr die Steine der Bindung finden?", completion = "Diese Steine der Bindung sind überaus mächtig. Wir haben den Feinden der Horde nicht nur einen schweren Schlag versetzt, sondern gleichzeitig eine faszinierende Quelle der Macht entdeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28460] = { id = 28460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch die Winterfelle", description = "Ich kam nach Winterquell, um die Frostfeuerquellen zu untersuchen. Mir ist aufgefallen, dass das Wasser... merkwürdige Eigenschaften zu haben scheint. Ich konnte die Quelle aber noch nicht entdecken, und um die Wahrheit zu sagen, hatte ich in letzter Zeit durch die Furbolgs der Winterfelle einige Schwierigkeiten.\n\nSie scheinen von den Quellen angezogen zu werden, genau wie ich. Mittlerweile wachen sie extrem eifersüchtig über das Wasser und lassen mich nicht einmal in die Nähe der beiden größeren Quellen, die von hier aus im Norden liegen.\n\nIch würde meine Studien aber gern fortsetzen. Könntet Ihr mir wohl helfen?", sourceObjective = "Tötet 15 Furbolgs der Winterfelle in der Nähe der Frostfeuerquellen.", completion = "Ich danke Euch vielmals, {name}! Jetzt kann ich mich hier wieder an die Arbeit machen.\n\nHabt Ihr im Lager der Winterfelle irgendetwas Interessantes gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[28461] = { id = 28461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschöpfe des Golemlords", description = "Die Zerschmetterte Hand meldet beunruhigende Informationen aus den Schwarzfelstiefen. Wie es scheint arbeitet der Schattenhammer mit dem Ingenieur der Dunkeleisenzwerge Argelmach zusammen, um durch Elementare beseelte Kriegsgolems zu erschaffen. Diese Golems könnten ein großer Vorteil für unsere Feinde sein.\n\nEs ist unsere Pflicht, dies zu verhindern. Findet die Manufaktur in den Schwarzfelstiefen, besorgt Euch die Blaupausen, mit denen er diese Golems erschafft, und beschafft die Module, die ihnen Leben einhauchen.", sourceObjective = "Beschafft 5 Elementarmodule von den Golems in der Manufaktur der Schwarzfelstiefen und stehlt die Baupläne für einen Elementargolem.", progress = "Wir dürfen nicht zulassen, dass sie diese Golems gegen uns einsetzen.", completion = "Könnt Ihr Euch vorstellen, was passiert wäre, wenn sie diese Modelle funktionstüchtig gemacht und auf das Schlachtfeld geschickt hätten? Ihr habt der Horde einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28462] = { id = 28462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerwasser der Winterfelle", description = "Diese Phiole, die Ihr bei den Winterfellfurbolgs aufgehoben habt, ist leer, aber Ihr könnt im Inneren ein paar Tropfen einer merkwürdigen grünen Flüssigkeit sehen. Sie scheint fast zu glühen.\n\nIst es etwas Wichtiges?\n\nDonova Schneeweh könnte Euch wahrscheinlich mehr sagen, da sie nun schon einige Zeit bei den heißen Quellen in Winterquell lagert.", sourceObjective = "Bringt das leere Feuerwasserfläschchen zu Donova Schneeweh in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[28463] = { id = 28463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Armee der Dunkeleisenzwerge", description = "Als Mitglied der Zerschmetterten Hand wisst Ihr, dass Eure Aufgabe darin besteht, die Feinde der Horde zu beobachten. Wir haben herausgefunden, dass die Dunkeleisenzwerge und ihre neuen Verbündeten vom Schattenhammer einen Angriff vorbereiten.\n\nIch entsende Euch, damit Ihr dieser Bedrohung Herr werdet, bevor die Dunkeleisenarmee ausrücken kann. Nehmt dieses Gift und gebt es auf die Rationen der Soldaten in den Schwarzfelstiefen.\n\nDie Rationen für die Armeen der Dunkeleisenzwerge werden größtenteils in der Ostgarnison und Westgarnison der Schwarzfelstiefen aufbewahrt.", sourceObjective = "Benutzt das schnell wirksame Gift, um 6 Getreiderationen in der Westgarnison oder Ostgarnison der Schwarzfelstiefen zu vergiften.", completion = "Wenn sie die vergifteten Rationen nicht so schnell entdecken, wird das ihre Ränge deutlich ausdünnen. Selbst wenn es den Großteil ihrer Truppen nicht tötet, wird es sie gehörig aufhalten. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28464] = { id = 28464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderbnis erliegen", description = "Die Aggressivität der Winterfelle muss irgendwo ihren Ursprung haben. Ich will der Sache auf den Grund gehen, wenn ich kann!\n\nIch habe gesehen, wie die Furbolgs in den Lagern im Norden etwas in einem Kessel gebraut haben. Sie schienen den Inhalt des Kessels mit Argusaugen zu bewachen... Wenn das, was sie darin kochen, der Grund ist, muss ich es mit eigenen Augen sehen!\n\nFindet den Kessel, wenn er noch dort ist, und bringt mir, was sich darin befindet!", sourceObjective = "Findet den Kessel der Winterfelle im nördlichen Lager der Winterfelle.", completion = "Im Kessel blubbert eine faulige, Ekel erregend riechende Substanz...", sourceObjectiveStatus = "unverified-source-field" }
quests[28465] = { id = 28465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklaven des Feuerlords", description = "In den Hallen der Schwarzfelstiefen versammeln der Schattenhammerkult und die Dunkeleisenzwerge ihre Streitkräfte. Ihre Legionen werden von Horden aus Feuerelementaren unterstützt, die der Feuerlord Ragnaros als Diener an sich gebunden hat.\n\nWenn wir die Elementare aus ihrem Bund befreien, können wir sowohl unsere Feinde schwächen als auch den Elementen Ehre erweisen. Nehmt dieses Totem und wirkt es auf die unterworfenen Brandwachen. Das wird ihre Geister befreien und ihren natürlichen Zustand wiederherstellen.", sourceObjective = "Benutzt das Totem der Freiheit, um die Essenzen von 6 Brandwachen, Brandwachenzerstörern oder lodernden Brandwachen in den Schwarzfelstiefen zu befreien.", completion = "Eure Taten ehren die Ahnen und die Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28466] = { id = 28466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Dunkelheit", description = "In den Schwarzfelstiefen hausen schon lange unsere Feinde, aber jetzt hat die Zerschmetterte Hand uns informiert, dass die Dunkeleisenzwerge und der Schattenhammer verstärkt zusammenarbeiten. Mit dem Wissen des Kultes verstärken die Dunkeleisenzwerge ihre Waffen mit elementaren Kräften. Sie haben die Legion der Zorneshämmer mit diesen schrecklichen neuen Waffen ausgerüstet.\n\nIch möchte, dass Ihr in die Schwarzfelstiefen reist und den Zwergen der Zorneshämmer ihre Waffen abnehmt. Zerbrecht sie auf dem Schwarzen Amboss im Herzen der Schattenschmiede.", sourceObjective = "Sammelt 5 elementarerfüllte Waffen von den Zwergen der Zorneshämmer in den Schwarzfelstiefen und zerbrecht sie auf dem Schwarzen Amboss in der Schattenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[28467] = { id = 28467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvoller Glibber", description = "Die grünliche Substanz im Kessel ist übelriechend und zähflüssig. Egal, was es ist, es sieht nicht gut aus.\n\nEs wäre das Beste, Donova von Euren Funden zu berichten und ihr eine Probe aus dem Kessel mitzubringen.", sourceObjective = "Berichtet Donova Schneeweh von Euren Entdeckungen.", progress = "Ich hoffe, Ihr habt etwas gefunden, {name}. Die Winterfelle werden immer aggressiver!", completion = "Das sind wirklich beunruhigende Neuigkeiten. Dieses Zeug erinnert mich mehr an den Teufelswald als an Winterquell...", sourceObjectiveStatus = "unverified-source-field" }
quests[28468] = { id = 28468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toxinschrecken" }
quests[28469] = { id = 28469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läufer der Winterfelle", description = "Sehr interessant, {name}...\n\nWenn diese toxische Substanz mit dem Wasser aus den heißen Quellen gemischt wird, verliert sie ihre Toxizität und behält lediglich die Fähigkeit zurück, Kreaturen vorübergehend zu beeinflussen, die sie einnehmen. Darum verteidigen die Winterfelle die heißen Quellen wohl so vehement - sie brauchen sie, um ihr Feuerwasser zu läutern.\n\nWir müssen sie aufhalten... den Kontakt zwischen den Winterfellen und den Totenwaldfellen abschneiden. Eine Gruppe von Läufern ist zwischen ihrem Dorf und dem Teufelswald unterwegs. Sucht und besiegt sie und stehlt ihre Lieferung.", sourceObjective = "Sucht den Läufer der Winterfelle und nehmt ihm die Kiste der Winterfelle ab.", progress = "Wir werden sehen, was passiert, wenn die Winterfelle ihr Feuerwasser nicht bekommen!", completion = "<Donova untersucht den Inhalt der Kiste.>\n\nIch frage mich, ob die Einnahme dieser Substanz die Furbolgs aggressiver macht. Sie wirken irgendwie viel größer...", sourceObjectiveStatus = "unverified-source-field" }
quests[28470] = { id = 28470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberhäuptling der Winterfelle", description = "Die Furbolgs der Winterfelle sind normalerweise kein aggressiver Stamm und diese Änderung ihres Verhaltens führt mich zu der Annahme, dass sie Befehle ihres Häuptlings ausführen. Wir werden wohl den Schaden, der bereits angerichtet ist, nicht mehr beheben können, aber ich denke, wenn ihr Anführer erledigt ist, wird es zumindest nicht schlimmer werden.\n\nGeht erneut nach Osten, jenseits des Ortes, an dem Ihr diesen Kessel gefunden habt. Der Oberhäuptling der Winterfelle befindet sich dort, am östlichsten Ende des Holzschlundpostens.", sourceObjective = "Tötet den Oberhäuptling der Winterfelle.", completion = "Ich danke Euch vielmals, {name}. Ich hoffe zu meinen Studien zurückkehren zu können, ohne Angst, dass ich in einen Hinterhalt gerate. Nehmt dies bitte als Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[28471] = { id = 28471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Stück", description = "Das Logbuch, das Ihr bei dem Oberhäuptling gefunden habt, scheint recht ausführlich zu sein, aber nachdem Ihr einige Seiten durchgesehen habt, stellt Ihr fest, dass Ihr den Text nicht lesen könnt. Die Zeichen sind so kunstlos und schlecht geformt, dass Ihr nicht sicher seid, ob überhaupt jemand sie lesen kann.\n\nAber vielleicht kann Donova Euch sagen, was sie bedeuten...", sourceObjective = "Bringt das kunstlos geschriebene Logbuch zu Donova Schneeweh in Winterquell.", progress = "Was habt Ihr da, {name}?", completion = "Ich frage mich, was das alles bedeutet... Ich kann mir keinen Reim darauf machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28472] = { id = 28472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte des Oberhäuptlings", description = "Die Winterfelle sind für mich keine Bedrohung mehr, aber wenn Ihr immer noch herausfinden möchtet, was die Furbolgs dazu gebracht hat, dieses merkwürdige Feuerwasser herzustellen und zu trinken, solltet Ihr Kelek Himmelshüter aufsuchen.\n\nEr ist ein Druide, der einst geholfen hat, den Teufelswald zusammen mit dem Smaragdkreis zu reinigen. Vor einer Weile ist er hierher gekommen, um die Ruinen in der Nähe zu untersuchen.\n\nIhr findet ihn wahrscheinlich im Osten am Kel'therilsee, wo er sich in letzter Zeit meist aufhält.", sourceObjective = "Bringt das kunstlos geschriebene Logbuch zu Kelek Himmelshüter am Kel'therilsee.", progress = "Was habt Ihr da bei Euch, {class}?", completion = "Ja, wenn Ihr es mich eine Weile untersuchen lasst, kann ich es für Euch vielleicht übersetzen.\n\n<Kelek blättert durch die Seiten.>\n\nWenn ich es ganz durchgesehen habe, werde ich Euch eine Nachricht schicken.\n\nDanke, dass Ihr dies mit mir teilt, {name}. Man weiß sehr wenig über die Winterfellfurbolgs.", sourceObjectiveStatus = "unverified-source-field" }
quests[28473] = { id = 28473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Dunkelheit", description = "In den Schwarzfelstiefen hausen schon lange unsere Feinde, aber jetzt hat die Zerschmetterte Hand uns informiert, dass die Dunkeleisenzwerge und der Schattenhammer verstärkt zusammenarbeiten. Mit dem Wissen des Kultes verstärken die Dunkeleisenzwerge ihre Waffen mit elementaren Kräften. Sie haben die Legion der Zorneshämmer mit diesen schrecklichen neuen Waffen ausgerüstet.\n\nIch möchte, dass Ihr in die Schwarzfelstiefen reist und den Zwergen der Zorneshämmer ihre Waffen abnehmt. Zerbrecht sie auf dem Schwarzen Amboss im Herzen der Schattenschmiede.", sourceObjective = "Sammelt 5 elementarerfüllte Waffen von den Zwergen der Zorneshämmer in den Schwarzfelstiefen und zerbrecht sie auf dem Schwarzen Amboss in der Schattenschmiede.", completion = "Eure Taten ehren Eure Brüder und die Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28474] = { id = 28474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers in den Schwarzfelstiefen wächst. Sie haben sich mit den Dunkeleisenzwergen verbündet und wollen sie überreden, auch außerhalb des Berges zuzuschlagen.\n\nWir müssen die Instrumente des aufwieglerischen Schattenhammers vernichten. Ihr Einfluss auf die Dunkeleisenzwerge muss eingeschränkt werden.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28475] = { id = 28475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers in den Schwarzfelstiefen wächst. Sie haben sich mit den Dunkeleisenzwergen verbündet und wollen sie überreden, auch außerhalb des Berges zuzuschlagen.\n\nWir müssen die Instrumente des aufwieglerischen Schattenhammers vernichten. Ihr Einfluss auf die Dunkeleisenzwerge muss eingeschränkt werden.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", completion = "Wir können nur hoffen, dass die beiden Streitmächte dank Eurer Bemühungen lange genug entzweit bleiben, um ihre Schwäche auszunutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28476] = { id = 28476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers in den Schwarzfelstiefen wächst. Sie haben sich mit den Dunkeleisenzwergen verbündet und wollen sie überreden, auch außerhalb des Berges zuzuschlagen.\n\nWir müssen die Instrumente des aufwieglerischen Schattenhammers vernichten. Ihr Einfluss auf die Dunkeleisenzwerge muss eingeschränkt werden.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28477] = { id = 28477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers in den Schwarzfelstiefen wächst. Sie haben sich mit den Dunkeleisenzwergen verbündet und wollen sie überreden, auch außerhalb des Berges zuzuschlagen.\n\nWir müssen die Instrumente des aufwieglerischen Schattenhammers vernichten. Ihr Einfluss auf die Dunkeleisenzwerge muss eingeschränkt werden.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28478] = { id = 28478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers in den Schwarzfelstiefen wächst. Sie haben sich mit den Dunkeleisenzwergen verbündet und wollen sie überreden, auch außerhalb des Berges zuzuschlagen.\n\nWir müssen die Instrumente des aufwieglerischen Schattenhammers vernichten. Ihr Einfluss auf die Dunkeleisenzwerge muss eingeschränkt werden.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28479] = { id = 28479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Kel'Theril", description = "An diesem See wurde der Kristall von Zin-Malor von den Hochgeborenen gestohlen. Der Kristall war ein mächtiges Artefakt, das arkane Magie auf wilde und nicht vorhersehbare Weise biegen konnte... doch es konnte nur von den Würdigen verwendet werden und stürzte alle anderen ins Verderben.\n\nDie Geister, die hier umherstreifen, umspannen ganze Generationen, die alle von Zin-Malor an diesen Ort gefesselt wurden. Einige sprechen und erzählen von ihrem Schicksal.\n\nFalls Ihr etwas über das Schicksal von Zin-Malor erfahren möchtet, sucht den Geist in der Mitte des Sees auf...", sourceObjective = "Sprecht mit dem Kaldoreigeist auf dem Kel'therilsee in Winterquell.", completion = "Bemitleidet mich, Fremder, und all die Hochgeborenen, denn an diesem Ort begann unsere Dummheit... Unsere Dummheit, die unsere Kinder verfluchte und die Kinder unserer Kinder bis zum heutigen Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[28480] = { id = 28480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offiziere der Dunkelheit", description = "Die Armeen von Ramkahen werden von Nefersets unsterblichen Wächtern vernichtet.\n\nDer einzige Weg, sie zu besiegen, besteht darin, den dunklen Pharao von Neferset zu töten.\n\nBevor wir jedoch zuschlagen, müssen wir erst seine Offiziere aus dem Weg räumen.\n\nBegebt Euch hinter die Kampflinien und tötet Skorpionfürst Namkhare und Hohepriester Sekhemet. Nur dann werden wir dem dunklen Pharao selbst gegenübertreten können.", sourceObjective = "Tötet Skorpionfürst Namkhare und Hohepriester Sekhemet.", completion = "Ihr seid ein wertvoller Verbündeter, {name}. Wir sind der Vernichtung unseres Feindes einen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28481] = { id = 28481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gequälten Seelen von Kel'Theril", description = "Die Geister der Hochgeborenen sind erbärmliche Kreaturen, das ist mal sicher. Sie suchen immer noch nach Teilen dessen, was sie für immer nach Kel'Theril verdammte - das gestohlene Relikt.\n\nWenn Ihr so daran interessiert seid, nehmt meine Hacke und geht nach Süden zum See. Seht, ob Ihr die Teile des Relikts aus dem Eis holen könnt.", sourceObjective = "Benutzt Gormirs Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28482] = { id = 28482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sullahs Geschenk", description = "Jonesy hat mir erzählt, dass Ihr beide auf den Berg dort hinauf müsst.\n\nNun, solange diese Soldaten dort überall wie Ameisen auf einer Leiche herumwuseln, wird Euch das kaum gelingen.\n\nEinige meiner Freunde konnten etwas Ausrüstung von unseren Feinden stehlen. Das sollte Eure Reise etwas erleichtern.\n\nBegebt Euch hinauf auf den Grat im Norden und Ihr werdet die Ausrüstung finden.\n\nViel Glück, Euch beiden!", sourceObjective = "Sprecht mit Harrison Jones an der Pilgerklippe.", completion = "Schön, dass Ihr es geschafft habt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28483] = { id = 28483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst den Feind bluten", description = "Ich werde Euch nicht belügen, {name}. Vor uns liegt eine riesige Herausforderung.\n\nWenn Ihr Euch in Neferset hinter feindliche Linien begebt, müsst Ihr mir die Insignien dieses Nefersetabschaums mitbringen.\n\nEs wäre ein Segen für unsere Armeen, wenn sie wüssten, dass Ihr dem Feind einen verheerenden Schlag versetzt habt.", sourceObjective = "Sammelt 10 Insignien aus Neferset.", progress = "Schön, Euch wiederzusehen, {name}.", completion = "Ausgezeichnete Arbeit, {name}. Unsere Truppen werden von Euren Taten erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28484] = { id = 28484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Herzensangelegenheit", description = "Der Magus ist schon zu lange unbeschäftigt, und unbeschäftigte Magier führen oft zu schlecht geplanten Intrigen. Dieses Mal ist es meine Aufgabe, verschiedene Tierorgane als Energiequelle für eine Art Kontrollstab zu sammeln. Ich bin viel zu zart, um auf Bestienjagd zu gehen, besonders wenn es sich dabei um Yetis handelt!\n\nWenn ich Euch eine Belohnung anbiete, würdet Ihr das dann übernehmen? Ihr müsst nur nach Westen in die Yetihöhlen gehen und Yetis töten. Reißt ihnen die noch schlagenden Herzen aus der Brust und bringt sie mir.", sourceObjective = "Sammelt 12 schlagende Yetiherzen.", progress = "Bringt mir Yetiherzen, {name}.", completion = "Ich... äh... nun... Es hat sich herausgestellt, dass er keine Herzen mehr braucht. Tut mir leid! Ich hoffe, Ihr hattet nicht allzu viele Probleme. Aber abgemacht ist abgemacht, also hier Eure Belohnung. Ihr dürft die Yetiherzen behalten. Wie ich höre haben sie ausgezeichnete Nährwerte, falls Ihr so etwas mögt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28485] = { id = 28485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetimus der Yetifürst", description = "Viele Jahre lang durften die Yetis in dieser Gegend sich selbst regieren. Unsere Selbstzufriedenheit in der Handhabung der Yetibedrohung hat jedoch zu einer Fehlentwicklung geführt. Yetimus, der Fürst aller Yetis, ist so groß und stark geworden, dass unsere Wache ihn einfach nicht mehr unter Kontrolle hat. Wenn sein Appetit ihn nach Tarrens Mühle führt, wird er uns vermutlich alle verschlingen.\n\nVersammelt eine Gruppe streitbarer Recken und beseitigt diese Bestie. Er streift im Westen durch das Land.\n\nBringt mir eines seiner Hörner und ich werde Euch fürstlich entlohnen.", sourceObjective = "Besorgt Yetimus' verdrehtes Horn.", progress = "Yetimus muss sterben!", completion = "Also ist es wahr! Ihr habt die Bestie getötet. Die Bewohner des Hügellands stehen in Eurer Schuld, {name}. Ihr habt das Land sicherer für unsere Bürger gemacht.\n\nNehmt aus unseren Kisten, was immer Euer Herz begehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28486] = { id = 28486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhets Schachzug", description = "Neferset ist zu gut verteidigt. Der Berg daneben jedoch nicht.\n\nIch habe mit dem Waldläuferhauptmann gesprochen. Er ist bereit, den strategisch gut gelegenen Berggipfel mit einigen seiner Leute zu sichern.\n\nEs gibt jedoch einen Haken, {name}. Er hat zwar zugestimmt, aber nur, wenn Ihr die Angriffsspitze bildet.\n\nEs muss eine kleine Gruppe sein, sonst ziehen wir zu früh die Aufmerksamkeit des Feindes auf uns, aber vertraut mir... die Waldläufer von Ramkahen sind so hart im Nehmen, wie es nur geht. Mit Euch an ihrer Seite werden wir sicher Erfolg haben.", sourceObjective = "Begleitet den Waldläuferhauptmann von Ramkahen an einen höher gelegenen Ort.", completion = "Ihr habt es geschafft, {name}! Ausgezeichnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[28487] = { id = 28487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humberts persönliche Probleme", description = "Also, das ist mir ein wenig peinlich. Wo soll ich nur anfangen?\n\nNun, seht Ihr, Melisara hat mich ausgeschickt, um die Yetibedrohung in den nahegelegenen Höhlen westlich von hier auszukundschaften. Es war schon spät und meine Rüstung wurde mir so schwer. Ich habe meine Sachen abgelegt und beschloss, mich ein wenig umzusehen. Ja, ich, äh, habe einen kleinen Spaziergang gemacht. Als ich jedenfalls zurückkam, waren meine Sachen gestohlen! Es waren die Yetis. Ich bin mir ganz sicher. Sie haben meine Hose, mein Schwert und meinen Helm genommen und sind in ihre Höhle geflüchtet. Bringt sie mir wieder, und ich werde Euch belohnen.", sourceObjective = "Holt Humberts Schwert, Humberts Helm und Humberts Hose zurück.", progress = "Ich bin hier fast nackt, {name}. Helft mir, ja?", completion = "Vielen Dank, {name}. Ich verspreche, dass ich diese Sachen nie wieder ablegen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[28488] = { id = 28488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter der Oberfläche", description = "In den Bruchtiefen, weit außerhalb unserer Reichweite, gibt es viele wertvolle Edelsteine, unter anderem auch riesige Rubinkristallklumpen. In ihnen steckt eine schreckliche Energie.\n\nEin solcher Klumpen wird schwer zu beschaffen sein, denn sie werden streng bewacht. Aber Ihr seid stur und tapfer. Ich glaube, Ihr könntet es schaffen.\n\nSucht in den Bruchtiefen nach Orten, an denen die Tunnel abrupt in Stein übergehen. Wenn überhaupt, werdet Ihr die Klumpen dort finden. Solltet Ihr einen entdecken, dann bringt ihn mir.", sourceObjective = "Beschafft einen riesigen Rubinkristallklumpen.", progress = "Diese Kristalle sind sehr wertvoll, vor allem für Gorsik. Sollte ich einen bekommen, werde ich große Macht über ihn gewinnen. Ich möchte, dass das geschieht.", completion = "Genau danach habe ich gesucht. Danke, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28489] = { id = 28489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hirschbrötchen", description = "Schon mal ein Hirschbrötchen gegessen? Ich auch nicht. Schmeckt angeblich toll. Essen interessiert mich nicht, Geschäfte schon. Meine Gäste wollen Hirschbrötchen, also kriegen sie welche.\n\nWahrscheinlich fragt Ihr Euch: \"Was geht mich das an?\". Die Antwort, {class}, lautet: Ich brauche Hirschfleisch! Ich bezahle Euch für jedes Stück Hirschfleisch, das Ihr mir von den Hügelhirschen des Hügellands bringt. Ist doch ein gutes Geschäft, oder?\n\nLegt los! Im Westen gibt es die meisten Hirsche.", sourceObjective = "Besorgt 8 Stück Hirschfleisch.", progress = "Ich brauche Hirschfleisch!", completion = "Ihr schleppt ja ganz schön was mit Euch herum. Das sollte meine Gäste für eine Weile zufriedenstellen.\n\nUnd wie versprochen: Hier, Eure Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[28490] = { id = 28490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Dunkelküste!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Priesterin Dentaria in Lor'danel an der Dunkelküste einzufinden.\n\nDie Einwohner von Lor'danel müssen sich um die kümmern, die Auberdines Zerstörung überlebt haben, und ihre Stadt vor dem Schattenhammer schützen. Dazu benötigen sie Eure Hilfe. Sprecht mit Vesprystus, dem Hippogryphenmeister in Rut'theran, außerhalb von Darnassus und erwerbt einen Flug zur Dunkelküste.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Priesterin Dentaria in Lor'danel an der Dunkelküste.", completion = "Der König hat unser Flehen erhört? Elune sei Dank! Wir können alle Hilfe gebrauchen, die man uns gewährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28491] = { id = 28491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht Stubenfliegen, Flammenfliegen", description = "Die meisten Bewohner verlassen den Flammenkamm früher oder später. Die Brennende Steppe ist ihnen wohl nicht SPANNEND genug.\n\nDas sehe ich anders. Ich finde immer einen Grund hier zu bleiben. Der neueste sind die Flammenfliegen, die seit kurzem hier auftauchen.\n\nBei Tag findet man sie nahe der Lava. Nachts sind sie fast überall.\n\nWenn Ihr Lust hättet, welche zu sammeln, würde sich das für Euch lohnen.", sourceObjective = "Beschafft 7 Flammenfliegen.", progress = "Und?", completion = "Gute Arbeit! Neue Haustiere für Kibler!", sourceObjectiveStatus = "unverified-source-field" }
quests[28492] = { id = 28492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Eschental!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Schildwache Shyela in Orendils Zuflucht im nordwestlichen Eschental einzufinden.\n\nDie Übergriffe der Horde auf das Eschental müssen aufhören! Eure Hilfe wird benötigt. Schlagt die Eindringlinge zurück und heilt den heiligen Wald. Reist nach Süden durch das Zwielichttal an der Dunkelküste, um zum Wald des Eschentals zu gelangen.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Schildwache Shyela bei Orendils Zuflucht im nordwestlichen Eschental.", completion = "Seid Ihr hier, um uns gegen die Streitkräfte der Horde zu unterstützen? Jede Klinge und jeder Zauber sind willkommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28493] = { id = 28493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Eschental!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kadrak am Schutzwall von Mor'shan zwischen dem Nördlichen Brachland und dem Eschental zu melden. Helft, die Nachtelfen aus dem Wald zu vertreiben, damit unser Volk seine Ressourcen nutzen kann!\n\nIhr erreicht den Schutzwall von Mor'shan, indem Ihr vom Wegekreuz im Nördlichen Brachland die Goldstraße Richtung Norden nehmt.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Kadrak am Schutzwall von Mor'shan zwischen dem Nördlichen Brachland und dem Eschental.", completion = "Ihr seid also die Verstärkung? Soll mir recht sein, solange Ihr Nachtelfen töten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28494] = { id = 28494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Nördliches Brachland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kargal Schlachtnarbe in der Fernwacht im Nördlichen Brachland zu melden.\n\nEure Hilfe wird bei der Verteidigung des Brachlands gegen eindringende Stacheleber und Zentauren benötigt.\n\nDie Fernwacht erreicht Ihr, indem Ihr westlich durch die Südstromaue von Durotar reist und die Brücke ins Nördliche Brachland nehmt.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht im Nördlichen Brachland.", completion = "Ihr seht aus, als könntet Ihr mit einer Waffe oder einem Zauberbuch umgehen. Helft uns, die Stacheleber aus dieser Gegend zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28495] = { id = 28495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstverteidigung", description = "Gesegnet sei das Licht! Ich brauche Eure Hilfe!\n\nAuf meinem Weg zum Hügellandhof bemerkte ich einige niedliche Rehfamilien. Ich wollte gerade ein kleines Kitz streicheln, als eine Bergkatze hervorsprang und es tötete. Ich floh nach Tarrens Mühle und schwor mir, das Leid der Hügelkitze zu lindern. Tagelang probierte ich herum, aber jetzt habe ich eine Lösung für die Hügelkitze gefunden!\n\nNehmt meinen Zauberstab, geht zu den Feldern im Westen und gebt den kleinen Hügelkitzen Kraft. Dann werden sie in der Lage sein, sich selbst zu helfen!", sourceObjective = "Rettet 10 Hügelkitze.", completion = "WAS!? Sagt das nicht, {name}! Das kann nicht sein! Mein... Ich... Ich würde nie...\n\nIch gebe nicht auf, {class}. Wartet nur ab. Ich werde diese Rehkitze retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28496] = { id = 28496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Azshara!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Ag'tor Blutfaust am Hinteren Tor von Orgrimmar in Azshara zu melden.\n\nHelft bei der Vertreibung der Allianzstreitkräfte und sichert Azshara zum Ruhm der Horde!\n\nVerlasst Orgrimmar durch das nördliche Tor, um zum Hinteren Tor von Orgrimmar in Azshara zu gelangen.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Arbeitsaufseher Grabbit am Hinteren Tor von Orgrimmar in Azshara.", completion = "Wir können Hilfe gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28497] = { id = 28497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer vom Himmel", description = "Sullah meinte es ernst. Auf dem Hügel wimmelt es von Truppen!\n\nSpringt auf und markiert die Ziele für mich.\n\nJeder Schuss muss sitzen, {name}! Der Weg nach oben muss frei sein.", sourceObjective = "Tötet 100 Soldaten von Schnottz, während Ihr auf der konfiszierten Artillerie sitzt.", completion = "Gute Arbeit, {name}.\n\nMal sehen, ob wir es nach oben schaffen, bevor sie sich erholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28498] = { id = 28498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis von Nahom", description = "Es gibt eine alte Geschichte über Nahom. Darin geht es um einen mächtigen Propheten namens Atulhet, der dem Ansturm seiner Feinde standhielt, indem er die Kraft der Sonne durch diesen Tempel hier leitete.\n\nDie meisten halten diese Geschichte für eine Legende, aber eine solche Macht... könnte uns jetzt sehr von Nutzen sein.\n\nDie abscheulichen Neferset haben Atulhets Grab geplündert. Sie haben alle Artefakte der Macht an sich genommen und die Tafeln, die seine Erinnerungen verschlüsselten, zerschlagen.\n\nGeht zu den Gräbern der Wegbereiter östlich von hier und bergt alle Fragmente, die Ihr findet.", sourceObjective = "Beschafft 8 von Atulhets Aufzeichnungsfragmenten.", progress = "Habt Ihr sie gefunden, {name}? Konntet Ihr sie bergen?", completion = "Hervorragend. Schauen wir mal, ob wir etwas Wichtiges finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28499] = { id = 28499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestraft die Eindringlinge", description = "Wir, die Priester von Nahom, bewachen die Gräber der Wegbereiter.\n\nSeit sich die Neferset ihrem neuen Herren unterworfen haben, begehen sie große Frevel.\n\nAuf der Suche nach mächtigen Artefakten plündern sie die Gräber unserer Vorväter und zerstören dabei wertvolle Relikte.\n\nSucht die Gruften östlich von hier auf und bestraft die Grabräuber. Sie dürfen sich ihren Brüdern nicht anschließen, wenn die Neferset Nahom angreifen.", sourceObjective = "Tötet 10 beliebige Eindringlinge von Neferset an den Gräbern der Wegbereiter.", completion = "Vielleicht seid Ihr wirklich so mächtig, wie ich gehört habe.\n\nEuch gebührt unser Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[28500] = { id = 28500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Chiffre von Keset", description = "<Priester scharen sich um Salhet, als er die Tafeln betrachtet.>\n\nEs ist alles hier, {name}. Atulhet baute eine mächtige Waffe in diesen Tempel ein. Ohne die korrekte Chiffre kann man sie nicht benutzen.\n\nAngeblich wurde sie auf dem Kesetpass versteckt. Hoffentlich haben die Plünderer von Neferset sie noch nicht gefunden. Räuberfürst Havat regiert dort. Er ist der skrupelloseste von allen.\n\nOhne Verstärkung könnte die Waffe jedoch unsere einzige Hoffnung bei der Verteidigung von Nahom sein.", sourceObjective = "Beschafft die Chiffre von Keset.", progress = "Habt Ihr den Kodex gefunden, {name}?", completion = "Es stimmt also? Es gibt ihn wirklich!", sourceObjectiveStatus = "unverified-source-field" }
quests[28501] = { id = 28501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Nahom", description = "Der Feind kommt... in großer Zahl.\n\nEs wird keine weitere Verstärkung geben. Hoffentlich können wir dem Angriff der Neferset standhalten.\n\nWenn Nahom fällt, wird Ramkahen folgen.\n\nGeht nach draußen und sprecht mit einem meiner Unteroffiziere, wenn Ihr bereit seid. Ich werde Euch mit all meinen Kräften bei der Führung der Streitkräfte unterstützen.", sourceObjective = "Sprecht mit einem Unteroffizier der Ramkahen und verteidigt Nahom bis zum Sieg.", progress = "Wir haben keine Zeit zu verlieren!", completion = "Geschafft, {name}! Wir haben Nahom gehalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28502] = { id = 28502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegsherr der Banditen", description = "Unsere Gesetze verlangen, dass die Verantwortlichen für diesen Überfall bestraft werden.\n\nDer Anführer der Banditen wird Kriegsfürst Ihsenn genannt.\n\nIhr findet ihn ganz im Westen der Wüste. Sorgt dafür, dass seine Übergriffe nicht ungestraft bleiben.", sourceObjective = "Tötet Kriegsfürst Ihsenn.", completion = "Ich danke Euch, {name}. Diese Barbaren müssen für ihre Taten bestraft werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28503] = { id = 28503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Tausend Nadeln!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Caryssia Jägermond in Neu-Thalanaar an der Grenze zwischen Feralas und Tausend Nadeln einzufinden.\n\nDie Schildwachen benötigen Eure Unterstützung gegen die plündernden Räuber der Grimmtotems, die diese Gegend terrorisieren. Neu-Thalanaar erreicht Ihr, indem Ihr ins östliche Feralas reist, nahe der Grenze von Tausend Nadeln.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Caryssia Jägermond in Neu-Thalanaar an der Grenze zwischen Feralas und Tausend Nadeln.", completion = "Ihr seid gerade rechtzeitig eingetroffen, {class}. Wir brauchen Eure Hilfe, um die Grimmtotems aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28504] = { id = 28504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Tausend Nadeln!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Nyse in Morastwinkel zu melden. Schließt Euch den Hordenstreitkräften im Kampf gegen die rebellischen Grimmtotems an, die das Gebiet beherrschen.\n\nNyse wird für den Transport zur Front sorgen. Sie wartet auf Euch im Gasthaus von Morastwinkel, das versteckt in den südlichen Düstermarschen liegt.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Nyse in Morastwinkel in den südlichen Düstermarschen. Ihr könnt auch einen Flug bei Doras in Orgrimmar buchen.", completion = "Die Streitkräfte der Horde in Tausend Nadeln brauchen dringend Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28505] = { id = 28505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Ich habe Neuigkeiten, <mein Freund/meine Liebe>. Es sieht nicht gut aus.\n\nDie Stadt Andorhal steckt mitten in einem dreiseitigen Krieg zwischen den Verlassenen, der Allianz und der Geißel. König Wrynn hat den Stein ins Rollen gebracht und einen seiner Todesritter entsandt, um den Sturmangriff für seine Sache zu leiten. Dennoch bin ich sicher, dass er jede Hilfe gebrauchen kann.\n\nIch lasse Euch nicht gern gehen, aber man hat Euch speziell angefordert, {name}. Sprecht draußen mit Guthrum Donnerfaust. Er wird Euch auf den ersten Greifen nach Andorhal setzen.", sourceObjective = "Sprecht mit Guthrum Donnerfaust und besorgt Euch einen Flug nach Andorhal in den Westlichen Pestländern. Meldet Euch dann bei Thassarian in Andorhal.", completion = "Das wurde auch Zeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28506] = { id = 28506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Marsch der Sturmlanzen", description = "Die Pläne, die Ihr besorgt habt, erzählen eine interessante Geschichte, {name}. Seit über einem Monat verlegen die Sturmlanzen ihre Armeen vom Alteractal in die \"vier Finger\" des Hügellands. Es ist ihnen gelungen, ohne das Wissen unserer Streitkräfte dort Anlagen zu errichten. Hätten wir diese Pläne nicht bekommen, wären sie uns in einer Woche entgegenmarschiert und hätten alles auf ihrem Weg vernichtet.\n\nDank dieser Pläne können wir den Spieß umdrehen.\n\nWir müssen Folgendes tun...", sourceObjective = "Beobachtet den Marsch der Sturmlanzen.", completion = "Wir müssen jetzt handeln. Die Sturmlanzen müssen vernichtet werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[28507] = { id = 28507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Tanaris!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kelsey Stahlfunken in Gadgetzan einzufinden.\n\nDie Allianz braucht Eure Hilfe, um Zugeständnisse des ortsansässigen Barons und Zugriff auf die wertvollen Ressourcen der Gegend zu bekommen. Nach Gadgetzan kommt Ihr, indem Ihr Euch von der Schimmernden Tiefe in Tausend Nadeln nach Süden wendet.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Kelsey Stahlblitz in Gadgetzan in Tanaris.", completion = "Wir müssen die Goblins von Gadgetzan auf unsere Seite ziehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28508] = { id = 28508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Ich habe gerade eine merkwürdige Nachricht erhalten. Wirklich merkwürdig...\n\nDie Stadt Andorhal steckt mitten in einem dreiseitigen Krieg zwischen den Verlassenen, der Allianz und der Geißel. Sylvanas hat anscheinend die Initiative ergriffen. Das Interessante daran ist, dass sie Todesritter Koltira Todesweber das Kommando übertragen hat.\n\nMan hat speziell nach Euch gefragt, {name}. Sprecht mit Kellen Kuhn, dem Fledermausführer. Er wird Euch auf die erste Fledermaus nach Andorhal setzen.", sourceObjective = "Sprecht mit Kellen Kuhn und fliegt nach Andorhal in den Westlichen Pestländern. Meldet Euch dann bei Koltira Todeweber in Andorhal.", completion = "Das wurde auch Zeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28509] = { id = 28509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Tanaris!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich bei Megs Schredderschreck in Gadgetzan zu melden. Sorgt dafür, dass die Horde und das Bilgewasserkartell Tanaris besetzen, bevor die Allianz das tut!\n\nNach Gadgetzan kommt Ihr, indem Ihr Euch von Fizzels und Pozziks Turbodampfer im Südosten von Tausend Nadeln nach Süden zum Strand wendet. Oder Ihr besorgt Euch einen Flug bei Doras in Orgrimmar.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Megs Schredderschreck in Gadgetzan in Tanaris. Ihr könnt auch einen Flug bei Doras in Orgrimmar buchen.", progress = "Es wird langsam Zeit!", completion = "Ich könnte Eure Hilfe brauchen, {class}. Diese verdammte Gnomenfrau versucht das Dampfdruckkartell auf ihre Seite zu ziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28510] = { id = 28510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Feralas!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Konu Runentotem in Camp Ataya in Feralas zu melden. Helft der Horde, den großen Wald gegen die Allianz und die Grimmtotems zu verteidigen.\n\nIhr erreicht Camp Ataya, indem Ihr von Desolace südlich nach Feralas reist.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Konu Runentotem in Camp Ataya in Feralas.", completion = "Es gibt viele Probleme in Feralas. Eure Hilfe ist mir willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28511] = { id = 28511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Feralas!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Telaron Windsegler in Träumersruh in Feralas einzufinden.\n\nDie Allianz braucht Eure Hilfe im Kampf gegen unsere Feinde, die Horde und die Grimmtotems. Ihr erreicht Träumersruh, indem Ihr von Desolace südlich nach Feralas reist.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Telaron Windsegler in Träumersruh in Feralas.", completion = "Eure Ankunft ist ein Zeichen von Elune, {class}. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[28512] = { id = 28512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Thoriumbruderschaft", description = "Die Dunkeleisenzwerge sind zwar intrigant und boshaft... aber nicht alle sind unsere Feinde. Ich habe schon einige Male mit den Zwergen der Thoriumbruderschaft gesprochen und sie waren stets hilfsbereit.\n\nEin Freund von mir, Jack Felsbein, kam vor kurzem in die Stadt und fragte, ob ich ihn auf eine Art Expedition begleiten würde. Es klang wichtig.\n\nIch habe gerade zu tun, aber vielleicht möchtet Ihr ja mitgehen? Reist nach Westen, zur Straße, die in die Sengende Schlucht führt. Ihr werdet ihn kurz hinter dem Ödland finden.", sourceObjective = "Sprecht mit Jack Felsbein am Thoriumvorstoß in der Sengenden Schlucht.", completion = "Na, was haben wir denn hier? Wollt Ihr helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28513] = { id = 28513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz der Hochgeborenen", description = "Vor zehntausend Jahren...\n\n... lebten die Hochgeborenen hier in großem Wohlstand. Wir blickten herab auf die gewöhnlichen Nachtelfen. Magie und Reichtum erfüllten all unsere Bedürfnisse. Wir gaben uns den Begierden und der Ablenkung hin. Und der Gier...\n\nDie Geister, die Ihr hier seht, sind erfüllt von Reue und Bedauern. Ihre Pein kettet sie hier fest. Wenn Ihr mehr von Kel'theril und Zin'malor erfahren wollt, müsst Ihr sie aus ihrer Not befreien.", sourceObjective = "Tötet 8 gepeinigte oder leidende Hochgeborene.", progress = "Der Tod ist nicht immer eine Erleichterung.", completion = "Der Kristall von Zin-Malor wurde ohne Skrupel aus einem weit entfernten Tempel gestohlen. Mit ihm konnte man das Arkane kontrollieren. Wir fieberten danach, spielten mit ihm und als er zerbrach, kam der Fluch über uns alle. Kel'theril litt, bis die Zerschlagung den Kristall endgültig zerstörte.\n\nDer Fluch von Zin-Malor fesselt alle, die hier nach seiner Macht suchen. Ich erlag als erstes der Versuchung. Tausende Jahre später traf es unsere lang verlorenen Nachfahren...", sourceObjectiveStatus = "unverified-source-field" }
quests[28514] = { id = 28514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouton Flammenstern", description = "Heutzutage verlasse ich die Sengende Schlucht kaum noch. Seit Monaten möchte ich einen Freund in der Brennenden Steppe besuchen, aber ich komme einfach nicht dazu.\n\nSein Name ist Mouton Flammenstern. Er ist zwar kein Mitglied der Bruderschaft, aber ein guter Freund und sehr vertrauenswürdig.\n\nKönntet Ihr ihm meine Grüße ausrichten? Ihr müsst nach Süden gehen, durch den Fuß des Schwarzfels. Reist immer weiter gen Süden, dann findet Ihr ihn.\n\nDanke.", sourceObjective = "Meldet Euch bei Mouton Flammenstern am Flammensternposten in der Brennenden Steppe.", completion = "Oh, Schlickfaust schickt Euch? Hah!\n\nWisst Ihr, weshalb man ihn Schlickfaust nennt? Fragt ihn einmal danach.", sourceObjectiveStatus = "unverified-source-field" }
quests[28515] = { id = 28515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouton Flammenstern", description = "Heutzutage verlasse ich die Sengende Schlucht kaum noch. Seit Monaten möchte ich einen Freund in der Brennenden Steppe besuchen, aber ich komme einfach nicht dazu.\n\nSein Name ist Mouton Flammenstern. Er ist zwar kein Mitglied der Bruderschaft, aber ein guter Freund und sehr vertrauenswürdig.\n\nKönntet Ihr ihm meine Grüße ausrichten? Ihr müsst nach Süden gehen, durch den Fuß des Schwarzfels. Reist immer weiter gen Süden, dann findet Ihr ihn.\n\nDanke.", sourceObjective = "Meldet Euch bei Mouton Flammenstern am Flammensternposten in der Brennenden Steppe.", completion = "Oh, Schlickfaust schickt Euch? Hah!\n\nWisst Ihr, weshalb man ihn Schlickfaust nennt? Fragt ihn einmal danach.", sourceObjectiveStatus = "unverified-source-field" }
quests[28516] = { id = 28516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrhunderte des Leids", description = "Ich habe nur wegen der Gerüchte, der Kristall von Zin-Malor könnte hier zu finden sein, zugestimmt, über eine Kooperation mit den Nachtelfen und der Allianz nachzudenken.\n\nDer Kristall ist ein mächtiges, uraltes Artefakt, dessen Zerstörung das Land verflucht und dessen Zusammenfügung kaum Linderung gebracht hat.\n\nAber ich kann mich den Geistern, die dort hausen, nicht stellen. Verhöhnt mich ruhig, wenn es sein muss, oder versucht es selbst. Vielleicht werden die gelassenen Geister in der Mitte des Sees ja zu Euch sprechen...", sourceObjective = "Sprecht mit dem Geist der Kaldorei in der Mitte des Kel'therilsees.", sourceObjectiveStatus = "unverified-source-field" }
quests[28517] = { id = 28517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heulende Eiche", description = "So, das ist sie... unsere neue Heimat. Vielleicht werde ich mich nirgends mehr wirklich zu Hause fühlen.\n\nDoch wir müssen den Nachtelfen dankbar sein. Ihr Volk heißt nicht jeden willkommen. Dass sie uns aufgenommen haben, spricht für ihr Vertrauen und ihren Großmut.\n\nGwen und Graumähne sind an der Heulenden Eiche in der eigentlichen Stadt. Sucht sie auf. Nehmt das Portal unter dem Baum nördlich von uns und begebt Euch zur Heulenden Eiche im Nordteil der Stadt.", sourceObjective = "Sprecht mit Genn Graumähne an der Heulenden Eiche in Darnassus.", completion = "Diese Eiche entstand mit Hilfe der Druiden aus einem Samen, der aus Gilneas kam. Sie steht für alles, was wir erlitten und alles, was wir erreicht haben.\n\nMöge sie uns stets daran erinnern, dass unser Fluch auch ein Segen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28518] = { id = 28518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbe der Hochelfen", description = "Vor einhundert Jahren...\n\nKam ich mit einer kleinen Gruppe anderer Hochelfen aus unserem Heimatland, Quel'Thalas. Wir suchten nach den uralten Rätseln Kel'therils... wir wollten wissen, warum es zerstört wurde.\n\nWir entdeckten Fragmente im Eis – Splitter eines Kristalls. Der Erzmagier, der uns begleitete, erlag schnell ihrem Einfluss. Wir waren zu dumm, um es rechtzeitig zu erkennen.\n\nSein Geist wandert südöstlich von hier zwischen denen umher, die er in den Wahnsinn trieb. Er klammert sich immer noch an die Erinnerung seines geliebten Splitters...", sourceObjective = "Besorgt Zin-Malors Erinnerung vom Geist des Erzmagiers Maenius.", progress = "Maenius war ein mächtiger Magier und ehrenwerter Elf. Sein Geist hatte ein so unwürdiges Schicksal nicht verdient.", completion = "Wir waren entsetzt, bevor wir starben. Entsetzt, weil jemand aus unserem edlen und nüchternen Volk so rasch in teuflische Besessenheit verfallen war. Wir starben als naive Narren, Opfer unserer unbekümmerten Voreingenommenheit.\n\nDie Lebenden wissen, dass sich diese Ereignisse wiederholen sollten... hier und mit dem Fall von Quel'Thalas im gesamten Elfenvolk.", sourceObjectiveStatus = "unverified-source-field" }
quests[28519] = { id = 28519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmerz der Blutelfen", description = "Vor einem Jahr...\n\n... erreichte die Legende des Kristalls von Zin-Malor Silbermond. Ich führte eine Gruppe der besten Krieger und Gelehrten in dieses Land. Wir brachten genügend Manakristalle mit, so dass niemand versucht sein würde, den Kristall zu probieren.\n\nDoch auch ohne unseren Hunger verderbte uns der Kristall. Als wir ihn in Besitz nahmen, verwandelte er alle außer mir in elende Bestien.\n\nDie elenden Geister wandern noch immer umher und suchen nach Lebenden, die sie an diesen See ketten können. Werdet Ihr sie von ihrem Leid erlösen... oder fliehen, um eines Tages auf sicherem Boden zu sterben?", sourceObjective = "Tötet 7 elende Geister oder elende Schreckgespenster am Kel'therilsee.", progress = "Trödelt nicht zu lang. Nur wenige fliehen aus Kel'theril.", completion = "Der lebende Weltenwanderer, der Euch hierher schickte, ertrug es nicht, unser Schicksal zu sehen. Er lief davon... eine weise Entscheidung.\n\nWenn nun wieder jemand den Kristall von Zin-Malor in Händen hält, werden alle in seiner Nähe verloren sein. Er hätte nie wieder zusammengefügt werden dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28520] = { id = 28520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Neferset", description = "Wir sind bereit zum Angriff, {name}.\n\nWenn wir den dunklen Pharao Tekahn töten, werden die unsterblichen Kolosse fallen und unseren Armeen den Weg nach Neferset ebnen.\n\nFindet und greift ihn furchtlos an. Ich werde dafür sorgen, dass Ihr nicht allein seid, wenn die Zeit seines Untergangs gekommen ist.", sourceObjective = "Tötet den dunklen Pharao Tekahn in Neferset in Uldum.", completion = "Es ist vollbracht. Wir haben die Neferset in ihrer eigenen Stadt geschlagen.\n\nIch wünschte, nun könnte mein Volk endlich in Frieden leben, aber es wird noch mehr Blutvergießen geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28521] = { id = 28521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Salfa", description = "Nicht nur die Furbolgs der Totenwaldfelle im Süden bedrohen uns mit der Verderbnis, sondern sie lauert auch im Osten und bei den Furbolgs der Winterfelle in Winterquell. Sprecht mit Salfa am Winterquelleingang auf der anderen Seite der Feste, wenn Ihr uns weiterhin unterstützen wollt. Ihr gelangt über den linken Pfad dorthin.", sourceObjective = "Reist durch die Holzschlundfeste und verlasst sie in Winterquell. Sprecht mit Salfa, der den Eingang zur Holzschlundfeste bewacht.", completion = "Seid gegrüßt, {class} – ich wache hier als Sprecher der Holzschlundfeste hier in Winterquell und als Verteidiger meines Stammes.\n\nUnsere Brüder, die Winterfelle, sind in diesem eisigen Land von der gleichen Verderbnis heimgesucht worden wie die Furbolgs von Teufelswald. Solltet Ihr den Furbolgs der Holzschlundfeste helfen wollen, würden wir dieses Angebot annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28522] = { id = 28522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktivität der Winterfelle", description = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, {name}. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber, wenn möglich, andere Furbolgstämme.\n\nDer Winterfellstamm zeigt uns gegenüber immer größere Feindseligkeit. Sie scheinen in Rage zu sein und ganz von ihrer Furcht und dem Hass auf alles beseelt, das sie nicht verstehen.\n\nDie Winterfelle tragen Geisterperlen bei sich, die sie offensichtlich nicht vor der Verderbnis schützen konnten. Bringt mir 10 dieser Perlen als Beweis dafür, dass Ihr ihre Reihen ausgedünnt habt.", sourceObjective = "Beschafft 10 Geisterperlen von Furbolgs der Winterfelle.", progress = "Wir danken Euch für alles, was Ihr für die Holzschlundfeste getan habt, {name}. Helft uns auch weiterhin, dann werdet Ihr Euch das Vertrauen und den Respekt meines Stammes verdienen.", completion = "Ich danke Euch für Eure Dienste, auch wenn sie mich traurig stimmen. Nehmt dies als Zeichen meines Danks.\n\nIch hoffe, dass Ihr uns auch weiterhin unterstützt, {name}. Wir haben nur wenige Verbündete und ohne Eure Hilfe könnten wir die Gefahren, die meinem Stamm drohen, nicht bewältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28523] = { id = 28523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Perlen für Salfa", progress = "Mein Vertrauen habt Ihr, {name}, aber das meines misstrauischen Stamms müsst Ihr Euch weiterhin verdienen. Es gibt etwas, mit dem Ihr dieses Vertrauen erlangen könnt.\n\nDie Winterfelle tragen Geisterperlen, die sie vor bösen Geistern beschützen sollen. Diese Perlen sind ihrem Zweck nicht gerecht geworden, da die Winterfelle selbst nun die Verderbnis verbreiten. Bringt mir die Geisterperlen gefallener Furbolgs der Winterfelle. Jeweils fünf Perlen werden Euren Ruf bei der Holzschlundfeste verbessern.", completion = "Wieder einmal beweist Ihr uns Eure Ehrenhaftigkeit! Ich werde dafür sorgen, dass Eure Taten sich bei meinem Volk herumsprechen.\n\nVergesst nicht, mir alle Winterfellperlen zu bringen, die Ihr findet. Jedes Mal, wenn Ihr mir neue Perlen bringt, werde ich mich in unserem Stamm für Euch einsetzen." }
quests[28524] = { id = 28524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Donova", description = "Donova Schneeweh ist eine großherzige Zwergin, die häufig bei den heißen Quellen zu finden ist. Sie sagt, sie würde ihre magischen Eigenschaften untersuchen.\n\nSie ist gütig und wird gern in unserem Stamm gesehen. Als die Winterfelle feindseliger wurden, begann sie nach der Ursache ihrer Verderbnis zu forschen.\n\nIch kann meinen Posten nicht verlassen, aber ich möchte ihr einen Korb mit Erfrischungen geben. Bitte bringt ihn ihr an meiner Stelle und sagt Ihr, dass wir ihren nächsten Besuch erwarten.", sourceObjective = "Bringt Salfas Korb zu Donova Schneeweh in Winterquell.", progress = "Willkommen bei den heißen Quellen. Was habt Ihr denn da?", completion = "Diese Furbolgs sind wirklich nett. Sie tun mir Leid. Aus Angst vor der Welt verstecken sie sich in ihrer Feste.\n\nIch kann sie verstehen. Die Furbolgs der Winterfelle sind ebenso feindselig geworden wie die im Teufelswald. Ich möchte, dass das aufhört... nicht nur wegen meiner Recherchen, sondern auch wegen meiner Freunde in der Holzschlundfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[28525] = { id = 28525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Krater von Un'Goro!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Williden Marschall an Marschalls Wehr einzufinden.\n\nIhr sollt im Namen der Allianz Marschalls Expeditionen unterstützen, die die Geheimnisse uralter Bestien, einzigartiger Flora und mächtiger Kristalle ergründen wollen. Den Krater von Un'Goro erreicht Ihr, wenn Ihr das westliche Tanaris verlasst und der Straße bis nach Marschalls Wehr folgt.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Williden Marschall an Marschalls Wehr im Krater von Un'Goro.", completion = "Meine Entdecker, Wissenschaftler und Gelehrten sind die besten in ganz Azeroth, aber um die Wahrheit über die Geschichte des Kraters und seiner Bewohner herauszufinden, benötigen wir Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28526] = { id = 28526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Krater von Un'Goro!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Williden Marschall an Marschalls Wehr zu melden. Unterstützt Marschalls Expeditionen bei der Entdeckung der Geheimnisse des Kraters von Un'Goro. Vielleicht wird die Horde die einzigartigen Bestien und Kristalle in diesem Krater in irgendeiner Weise verwenden können.\n\nDen Krater erreicht Ihr, wenn Ihr die Straße nehmt, die aus dem westlichen Tanaris in den Krater führt, und ihr bis nach Marschalls Wehr folgt. Oder Ihr besorgt Euch einen Flug bei Doras in Orgrimmar.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Williden Marschall in Marschalls Wehr im Krater von Un'Goro. Ihr könnt auch einen Flug bei Doras in Orgrimmar buchen.", completion = "Willkommen, {class}. Meine Wissenschaftler und Entdecker werden für Eure Hilfe dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[28527] = { id = 28527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Silithus!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Windruferin Prachthorn in Burg Cenarius zu melden. Unterstützt unsere Verbündeten in ihrem Kampf gegen den Schattenhammer. Cho'galls Handlanger dürfen Silithus nicht beherrschen!\n\nUm nach Silithus zu gelangen, müsst Ihr der nordwestlichen Straße aus dem Krater von Un'Goro folgen. Oder Ihr besorgt Euch einen Flug bei Doras in Orgrimmar.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Windruferin Prachthorn in Burg Cenarius in Silithus. Ihr könnt auch einen Flug bei Doras in Orgrimmar buchen.", completion = "Willkommen in Burg Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28528] = { id = 28528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Silithus!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Windruferin Prachthorn auf Burg Cenarius einzufinden.\n\nUnsere Verbündeten vom Zirkel des Cenarius benötigen Eure Unterstützung im Kampf gegen den Schattenhammer. Ihr gelangt nach Silithus, indem Ihr die nordwestliche Straße aus dem Krater von Un'Goro nehmt.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Windruferin Prachthorn in Burg Cenarius in Silithus.", completion = "Willkommen in Burg Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28529] = { id = 28529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schriftstücke der Leere", description = "Die Schriften sind vage und scheinen Teil eines größeren Rätsels zu sein. Ihr vermutet jedoch, dass sie einige Angaben über den zu beschreitenden Weg, ein Dämonenjäger zu werden, enthalten.\n\nDie meisten Nachtelfen lehnen die dunklen Schwüre und Rituale ab, die angehende Dämonenjäger benötigen, also würden sie diese Schriften wahrscheinlich gern geheim halten.\n\nWaldläuferin Glynda Nal'Shea wird wissen, was mit diesen Schriftrollen anzufangen ist.", sourceObjective = "Bringt die Schriften des dunklen Herolds zu Waldläuferin Glynda Nal'Shea in Lor'danel.", progress = "Was kann ich für Euch tun, {class}?", completion = "Wo habt Ihr die gefunden?! Ihr habt sie doch niemand anderem gezeigt, oder?\n\nEntschuldigt. Ihr habt mich auf dem falschen Fuß erwischt. Telarius war ein mächtiger Dämonenjäger, der vor vielen Jahren im Kampf gegen die Wächterin Maiev fiel. Ihr habt Glück, dass sein Geist nur noch ein Schatten seiner selbst war. Ich frage mich, wie viele den Weg zu ihm in den Ruinen gefunden haben.\n\nIch werde dafür Sorge tragen, dass diese Schriftrollen sofort zur Hohepriesterin gebracht werden. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28530] = { id = 28530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brühende Zeichen", description = "In diesem Kessel scheint sich konzentriertes Material befunden zu haben. Wenn die Winterfelle dieses Zeug in den Quellen verdünnen, würden sie mit der Zeit verseucht werden... wodurch die Lösung zunehmend an Wirksamkeit verlieren würde.\n\nAn der Quelle nordöstlich von hier wimmelt es von Elementaren. Ich dachte, das hinge mit dem Kataklysmus zusammen, doch es könnte auch eine Reaktion darauf sein.\n\nWürdet Ihr bei ihnen nach Anzeichen der Verderbnis suchen? Jagt einige Elementare und bringt mir den fremdartigen grünen Stoff, den sie hinterlassen.", sourceObjective = "Beschafft 7 Stücke verdächtigen grünen Schlick von brühenden Quellbrandern oder kochenden Quellgurglern.", progress = "Was habt Ihr gefunden?", completion = "Das ist ziemlich viel... die Winterfelle rutschen stetig weiter ab. Und nun müssen wir uns auch noch um die anderen Wildtiere sorgen, aber eines nach dem anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28531] = { id = 28531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Desolace!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Offizierin Jankie auf der Straße nach Desolace in Tethris Aran einzufinden.\n\nDie mutigen Soldaten der Nijelspitze werden von Dämonen und den Armeen der Horde heimgesucht. Sie brauchen Eure Hilfe. Nehmt die Straße nach Süden, die aus dem Verbrannten Tal im Steinkrallengebirge führt, dann gelangt Ihr nach Desolace.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Jankie in Tethris Aran in Desolace.", completion = "Ich kann Euch auf schnellstem Weg zur Nijelspitze bringen! Wir brauchen dringend Verstärkung.", sourceObjectiveStatus = "unverified-source-field" }
quests[28532] = { id = 28532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Steinkrallengebirge!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Blutwache Aldo Steinregen in der Silberwindzuflucht im Eschental zu melden. Ihr müsst die Streitkräfte der Horde im Steinkrallengebirge in ihrem Kampf gegen die Eindringlinge der Allianz verstärken und unser Volk beschützen. Die Blutwache wird Euch den Weg zur Grenze des Steinkrallengebirges weisen.\n\nUm die Silberwindzuflucht zu erreichen, müsst Ihr ins Herz des Eschentals reisen und Euch unseren Streitkräften nahe des Sees anschließen.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Blutwache Aldo Steinregen in der Silberwindzuflucht im Eschental.", completion = "Lasst Ihr Euch ins Steinkrallengebirge versetzen? Gut. Wir werden Eure Fähigkeiten brauchen, um den Sieg über die Allianz davonzutragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28533] = { id = 28533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entscheidung des hohen Rates", description = "Der hohe Rat wird nun seine Entscheidung über den Krieg gegen den Stamm der Neferset fällen.", sourceObjective = "Sprecht mit König Phaoris in Ramkahen in Uldum.", completion = "Zwei Meldungen sind heute bei mir eingetroffen, {class}.\n\nDer Hohe Rat hat eine Entscheidung über den Krieg getroffen, und mein Bruder wurde vom Nefersetabschaum erschlagen.\n\nIch muss nicht länger warten, bis der Rat mein Volk in den Krieg führt. Sobald alle bereit sind, werden wir gegen die Neferset vorrücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28534] = { id = 28534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachkommen der Hochgeborenen", description = "Kurz nach meinem Tod wurde mein Volk wegen seiner Gier verbannt. Einen Kontinent entfernt wurden aus ihnen die Quel'dorei, die Hochelfen. In Quel'Thalas sonnten sie sich in der Macht ihres Sonnenbrunnens und vergaßen das Verlangen und die Gier, die ihnen anhafteten.\n\nDie Hand des Schicksals führte ihre weit entfernten Nachkommen hierher und zwang sie, die Geschichte zu wiederholen. Hört ihre Geschichte, so wie ich es getan habe...", sourceObjective = "Sprecht mit dem Geist der Quel'dorei.", completion = "Wir waren stolz und edel. Unser Glaube an das Licht schützte uns und der Sonnenbrunnen gab uns alles, was wir wollten.\n\nDiese Blindheit war schuld daran, dass wir an diesem Ort unsere tragische Geschichte wiederholen mussten - und später unser gesamtes Volk.", sourceObjectiveStatus = "unverified-source-field" }
quests[28535] = { id = 28535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachkommen der Hochelfen", description = "Lange nach meinem Tod beging mein Volk einen noch größeren Fehler. Die Hochelfen verließen sich auf den Sonnenbrunnen in all seiner Glorie. Wir konnten uns eine Welt ohne ihn nicht vorstellen, deshalb trafen wir nie Vorkehrungen für einen solchen Fall.\n\nAls der Sonnenbrunnen schließlich den Untoten in die Hände fiel, waren meine Nachkommen verloren und hilflos... der Weg, den sie daraufhin einschlugen, sollte sie auf ewig verändern.\n\nDie Sin'dorei, die immer noch nach Wiedergutmachung strebten, kamen ebenfalls hierher...", sourceObjective = "Sprecht mit dem Geist der Sin'dorei.", completion = "Wir waren nicht so naiv wie unsere Vorväter. Wir waren misstrauisch und listig und witterten überall Verrat.\n\nDoch unser Stolz und unsere Gier trieben uns wieder in den Untergang. Wie viele werden Kel'theril noch zum Opfer fallen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28536] = { id = 28536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch von Zin-Malor", description = "Ihr habt genug gesehen. Der Kristall von Zin-Malor bringt allen in seiner Nähe nichts als Unglück.\n\nVerlasst diesen Ort, wenn Ihr nicht wie wir werden wollt.", sourceObjective = "Kehrt zu Kelek Himmelshüter am Kel'therilsee in Winterquell zurück.", completion = "Der Schatten! Ja, ich habe ihn auch gesehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28537] = { id = 28537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf Schatten", description = "Ihr sagt, er habe von einem Meister gesprochen? Einem, der Zin-Malor besitzt?\n\nDas sind schlimme Neuigkeiten. Ihr müsst handeln, {class}! Ich sah den Schatten gen Süden fliegen. Nehmt den Pfad zu den oberen Ruinen und versucht den gefroreren Wasserfall dahinter zu besteigen!\n\nUnd seid vorsichtig... er wartet vielleicht auf Euch.", sourceObjective = "Jagt und tötet den Schatten des Geistsprechers und sucht nach Hinweisen auf seinen Meister.", progress = "Habt Ihr den Schatten gefunden? Gab es Hinweise auf seinen Ursprung?", completion = "Lasst mal sehen... zwischen den eingravierten Beschwörungen steht kaum erkennbar der Name seines Meisters!\n\n\"Umbranse...\"", sourceObjectiveStatus = "unverified-source-field" }
quests[28538] = { id = 28538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrei der Banshee", description = "Ihr sollt also <unser Retter/unsere Retterin> sein? Nun denn, ich werde mich mit Euch verbinden. Durch diese Verbindung kann ich durch Eure Augen blicken und mit Euch dort draußen kommunizieren.\n\nLaut der Pläne, die Ihr uns gebracht habt, nehmen die Sturmlanzen die Hilfe des SI:7 bei Soferas Landspitze nördlich von hier in Anspruch. Der SI:7 besteht vollständig aus Menschen – Menschen, die wir zu unserem Vorteil nutzen können.\n\nNehmt meinen Spiegel und geht nach Norden. Kämpft gegen Mitglieder des SI:7, bis sie dem Tode nahe sind. Benutzt den Spiegel, wenn sie verwundet sind.", sourceObjective = "Fasst 10 SI:7-Agenten mit Hilfe des Bansheespiegels.", sourceObjectiveStatus = "unverified-source-field" }
quests[28539] = { id = 28539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Steinkrallengebirge!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Jägerin Jalin an der Sternenstaubspitze im Eschental einzufinden.\n\nDie Streitkräfte der Horde versuchen, ins Steinkrallengebirge vorzudringen. Wir müssen sie aufhalten! Die Sternenstaubspitze liegt im südlichen Teils des Eschentals, nahe der Grenze zum Steinkrallengebirge.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Jägerin Jalin an der Sternenstaubspitze im Eschental.", completion = "Die Horde hat einen riesigen Pass in die Berge geschlagen. Wir können kaum Schildwachen entbehren. Wir müssen sie irgendwie aufhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28540] = { id = 28540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenstarke E'komagie", description = "Mau'ari macht seit Jahren Glücksbringer aus den Geistern der Wildnis. Mau'ari PFLÜCKT das E'ko einfach aus den Tieren und macht Glücksbringer für die Kinder und die Abenteurer.\n\nIm Osten gibt es einen großen Hügel, der von Splitterzahnbären umzingelt wird. Auf dem Hügel lebt Reifpelz, der älteste Bär des Waldes.\n\nMau'ari braucht den Bär für ihre Magie. Bringt mir das große, alte Herz des Bären.", sourceObjective = "Beschafft Reifpelz' Herz.", progress = "Habt Ihr den Bären erwischt? Lasst mal seh'n.", completion = "Das ist ein schönes, großes Herz! Mau'ari kann Euch zeigen, wie man das E'ko kriegt...", sourceObjectiveStatus = "unverified-source-field" }
quests[28541] = { id = 28541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behälter von Mau'ari", description = "E'ko kann man schwer beschreiben, aber alle Kreaturen in diesem Land besitzen es... Tiere, Furbolgs, sogar die Frostriesen. Man muss nur seinen Geist öffnen und wissen, wo man suchen muss...\n\nSeht mir zu, dann erfahrt Ihr, wie man das E'ko herauszieht.", sourceObjective = "Seht zu, wie Hexendoktorin Mau'ari das E'ko aus Reifpelz' Kadaver zieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28542] = { id = 28542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Teufelswald!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Tenell Laubschleicher im Smaragdrefugium in Teufelswald zu melden. Der Zirkel des Cenarius versucht, Teufelswald den Dämonen und anderen verderbten Kreaturen zu entreißen. Eure Hilfe wird benötigt! \n\nDas Smaragdrefugium liegt nördlich vom Eschental. Folgt der Straße bis zum Refugium.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Tenell Laubschleicher im Smaragdrefugium in Teufelswald.", completion = "Willkommen. Meine Brüder und ich widmen uns der Erlösung und Wiederbelebung dieses einst heiligen Waldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[28543] = { id = 28543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Teufelswald!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Tenell Laubschleicher im Smaragdrefugium einzufinden.\n\nVon Euch wird verlangt, den Teufelswald von den dämonischen Kräften zu befreien, die den Wald beherrschen. Begebt Euch in den Norden des Eschentals und folgt der Straße zum Teufelswald, bis Ihr das Smaragdrefugium erreicht.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Tenell Laubschleicher im Smaragdrefugium im Teufelswald.", completion = "Wir haben viel zu tun. Der Wald heilt, aber ohne unsere Hilfe wird es Generationen dauern, bis diese ehemals heiligen Bäume wiederhergestellt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28544] = { id = 28544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Winterquell!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Donova Schneeweh an den Frostfeuerquellen einzufinden.\n\nHelft ihr, die Bedrohung durch die Winterfelle abzuwenden. Reist aus dem nördlichen Teufelswald gen Osten und durch die Holzschlundfeste nach Winterquell.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Donova Schneeweh an den Frostfeuerquellen in Winterquell.", completion = "Gut, dass Ihr hier seid. Ich habe das Geheimnis der aggressiven Winterfelle entdeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28545] = { id = 28545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Winterquell!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Donova Schneeweh an den Frostfeuerquellen zu melden. Sie hat etwas über die Furbolgs der Winterfelle herausgefunden, das uns bei der Beseitigung dieser Bedrohung helfen könnte.\n\nDie Frostfeuerquellen liegen in Winterquell. Reist aus dem nördlichen Teufelswald nach Osten und durchquert die Holzschlundfeste.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Donova Schneeweh an den Frostfeuerquellen in Winterquell.", completion = "Ich glaube zu wissen, weshalb die Furbolgs der Winterfelle so stark geworden sind, aber ich hoffe, dass Ihr meinen Entdeckungen Sinn verleihen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28546] = { id = 28546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Winterfelle", description = "In Winterquell leben fehlgeleitete Kreaturen, die man Furbolgs der Winterfelle nennt. Dieses Bärenvolk ist so wütend und wild, dass es in ständiger Raserei lebt.\n\nBringt mir das E'ko der Winterfelle, dann versetze ich Euch in eine so starke Raserei, dass Eure Beine schnell wie der Wind sein werden!Ihr erlernt:", sourceObjective = "Beschafft 5 E'ko der Winterfelle von beliebigen Furbolgs der Winterfelle in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[28547] = { id = 28547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Winterfelle", description = "In Winterquell leben fehlgeleitete Kreaturen, die man Furbolgs der Winterfelle nennt. Dieses Bärenvolk ist so wütend und wild, dass es in ständiger Raserei lebt.\n\nBringt mir das E'ko der Winterfelle, dann versetze ich Euch in eine so starke Raserei, dass Eure Beine schnell wie der Wind sein werden!Ihr erlernt:", sourceObjective = "Beschafft 3 E'ko der Winterfelle von beliebigen Furbolgs der Winterfelle in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[28548] = { id = 28548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Desolace!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Furien in Tethris Aran in Desolace zu melden. Die tapferen Hordenkrieger von Desolace brauchen Eure Hilfe. Ihnen stehen die Armeen der Allianz und uralte Dämonen gegenüber.\n\nNehmt die Straße nach Süden, die aus dem Verbrannten Tal im Steinkrallengebirge führt, dann gelangt Ihr nach Tethris Aran.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Furien in Tethris Aran in Desolace.", completion = "Ihr... kommt gerade noch... rechtzeitig...", sourceObjectiveStatus = "unverified-source-field" }
quests[28549] = { id = 28549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Südliches Brachland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland zu melden. Die Allianz hat in letzter Zeit einige Siege im Brachland erfochten. Nun drohen sie unsere Nachschublinien abzuschneiden. Dann säßen unsere Krieger fest. Wir müssen handeln!\n\nReist aus dem Steinkrallengebirge gen Osten, dann gelangt Ihr zum Höhenpfad. Falls nötig könnt Ihr Euch auch einen Flug bei Doras in Orgrimmar besorgen.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland. Ihr könnt auch einen Flug bei Doras in Orgrimmar buchen.", progress = "Wir müssen schnell handeln!", completion = "Ihr dürftet bemerkt haben, was die Allianz dem Brachland angetan hat, {class}. Wenn wir nicht handeln, wird es hier bald keine Horde mehr geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28550] = { id = 28550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Südliches Brachland!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kommandant Walpole am Steinkrallenpass im Südlichen Brachland einzufinden.\n\nUnsere tapferen Soldaten sind tief ins Brachland vorgestoßen, doch dafür haben sie einen hohen Preis bezahlt! Sie benötigen Eure Hilfe, um das eroberte Land zu halten. Reist im Steinkrallengebirge südöstlich durch das Hochwipfeltal, dann gelangt Ihr ins Südliche Brachland.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Kommandant Walpole am Steinkrallenpass im nordwestlichen Teil des Südlichen Brachlands.", completion = "Tagtäglich schlagen wir uns mit schweren Gegenangriffen der Horde herum, {class}. Eine helfende Hand können wir sehr gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28551] = { id = 28551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Südliches Brachland!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Dockmeister Lewis nahe der Feste Nordwacht einzufinden.\n\nUnsere tapferen Soldaten sind tief ins Brachland vorgestoßen, doch dafür haben sie einen hohen Preis bezahlt! Sie benötigen Eure Hilfe, um das eroberte Land zu halten. Zu den Docks vor der Feste Nordwacht gelangt Ihr, indem Ihr das Schiff von Beutebucht nach Ratschet nehmt und dann entlang der Küste in südliche Richtung reist.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Dockmeister Lewis vor der Feste Nordwacht im Südlichen Brachland.", completion = "Die Horde leistet starken Widerstand, {class}. Jede Verstärkung ist uns willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28552] = { id = 28552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Düstermarschen!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Calia Hastings auf der Insel Theramore einzufinden.\n\nUnterstützt Calia Hastings vom SI:7 bei der Suche nach den Gefahren, die im Inneren von Theramore und außerhalb seiner Mauern lauern. Die Insel Theramore erreicht Ihr entweder, indem Ihr in Menethil ein Schiff besteigt oder vom Südlichen Brachland durch die Marschen reist.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Calia Hastings auf der Insel Theramore in den Düstermarschen.", completion = "Desertierte Stadtwachen sorgen für Unzufriedenheit bei den Soldaten. Wir müssen dem auf den Grund gehen, bevor unsere Verteidigungsfähigkeit beeinträchtigt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[28553] = { id = 28553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrilla und die Verwüsteten Lande", description = "Ich muss Euch eine letzte Nachricht überbringen, {name}. Sie stammt aus der Feste Schreckensfels in den Verwüsteten Landen südlich von hier.\n\nKriegsmatrone Okrilla kämpft gegen die Allianzstreitkräfte von Burg Nethergarde. Sie benötigt Unterstützung, <ein beherzter/eine beherzte:c> {class} wird gebraucht. Da hat man sofort an Euch gedacht.\n\nReist gen Süden in die Verwüsteten Lande, dann weiter nach Westen. Viel Glück, {name}.", sourceObjective = "Meldet Euch bei Kriegsmatrone Okrilla in Feste Schreckenfels in den Verwüsteten Landen.", completion = "Nun, seht mal an... unter welchem Stein hat man Euch denn gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[28554] = { id = 28554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Düstermarschen!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Krog in Brackenwall zu melden. In den Marschen wimmelt es von den unterschiedlichsten Feinden und die Streitkräfte der Allianz sind gefährlich stark.\n\nDie Düstermarschen erreicht Ihr, indem Ihr dem Pfad im östlichen Teil des Südlichen Brachland in Richtung Brackenwall folgt. Oder Ihr besorgt Euch einen Flug bei Doras in Orgrimmar.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Krog in Brackenwall in den Düstermarschen. Ihr könnt auch einen Flug bei Doras in Orgrimmar buchen.", completion = "Wenn wir den Sumpf unter Kontrolle bringen, könnten wir die Allianz angreifen, während die meisten ihrer Truppen im Brachland beschäftigt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28555] = { id = 28555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weist die Abgesandten aus" }
quests[28556] = { id = 28556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht die Hand", description = "Wenn wir die Übergriffe der Sturmlanzen beenden wollen, müssen wir ihnen die Finger brechen.\n\n<Cromush reicht Euch ein kleines Paket.>\n\nIn dem Paket befinden sich vier starke Sprengladungen der Goblins. Infiltriert die vier Finger - Soferas Landspitze, Corrahns Dolch, die Landzunge und Gavins Landspitze - und platziert in jedem eine goblinische Hosentaschenbombe.\n\nWenn Ihr das getan habt - und alles andere, um das Melisara Euch bittet - kehrt zu mir zurück.", sourceObjective = "Platziert eine goblinische Hosentaschenbombe bei Soferas Landspitze, Corrahns Dolch, der Landzunge und Gavins Landspitze.", completion = "Wenn Melisara mit Euch fertig ist, werden wir die Sprengladungen zünden!", sourceObjectiveStatus = "unverified-source-field" }
quests[28557] = { id = 28557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Uldum!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Adarrah im Disteltal in Tanaris zu melden.\n\nIn uralten Schriften ist zu lesen, dass in Uldum unfassbare Reichtümer und unvergleichliche Schätze liegen. Geht hin und holt sie Euch im Namen der Horde!\n\nIhr könnt Adarrahs Karawane erreichen, indem ihr in den südwestlichen Teil von Tanaris reist und dort im Disteltal nach ihr sucht.\n\nDas Schicksal ruft!", sourceObjective = "Sprecht mit Adarrah im Disteltal im westlichen Tanaris.", completion = "Ihr könntet zu den ersten Sterblichen gehören, die Uldum seit Jahrtausenden betreten. Denkt nur an die Schätze, die uns dort erwarten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28558] = { id = 28558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Uldum!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Adarrah im Disteltal in Tanaris einzufinden.\n\nSchließt Euch denen an, die als erste das ruhmreiche Uldum betreten und seine Schätze im Namen der Allianz an sich bringen!\n\nAdarrahs Karawane erreicht Ihr, indem Ihr zu den westlichen Ausläufern Tanaris' reist.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Sprecht mit Adarrah im Disteltal im westlichen Tanaris.", completion = "Jenseits dieses Tals warten Wunder nur darauf entdeckt zu werden! Sie werden uns gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[28559] = { id = 28559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Blutmythosinsel!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Vorkhan dem Elekktreiber in Kessels Wegelager einzufinden.\n\nHelft den Bewohnern der Blutmythosinsel im Kampf gegen verräterische Blutelfen und gefährliche Kreaturen, die auf der Insel ihr Unwesen treiben. Kessels Wegelager liegt auf der Blutmythosinsel. Reist zur Azurmythosinsel und nehmt die Brücke nach Norden.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Vorkhan dem Elekktreiber in Kessels Wegelager auf der Blutmythosinsel.", completion = "Wollt Ihr uns helfen? Es gibt viel zu tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[28560] = { id = 28560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Geisterlande!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Arkanist Vandril in Tristessa in den Geisterlanden zu melden.\n\nWerft die zahllosen Eindringlinge der Geißel zurück und sichert Euch die Hilfe der Verlassenen im Kampf gegen unseren gemeinsamen Feind.\n\nNehmt die Straße, die von Morgenluft nach Süden in die Geisterlande führt, um nach Tristessa zu gelangen.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Arkanist Vandril in Tristessa in den Geisterlanden.", completion = "Eure Ankunft ist ein Glücksfall, {class}. Wir benötigen Hilfe im Kampf gegen die Geißel.", sourceObjectiveStatus = "unverified-source-field" }
quests[28561] = { id = 28561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahom muss gehalten werden", description = "Wenn wir nach Westen aufbrechen, um Neferset anzugreifen, wird der Feind unsere Schwäche im Osten ausnutzen und dort zuschlagen.\n\nNahom wird als erstes fallen und dann Ramkahen.\n\nEin kleiner Stoßtrupp ist bereits dort.\n\nDie Soldaten werden Euch alles erklären. Sorgt dafür, dass sie Nahom halten, bis ich weitere Truppen schicken kann.", sourceObjective = "Meldet Euch beim Regiment in Nahom in Uldum.", completion = "{name}! Ihr seid es! Mein Regiment wurde auf dem Weg hierher angegriffen.\n\nUnser Hauptmann wurde getötet und ich musste das Kommando übernehmen... aber jetzt seid Ihr ja da!", sourceObjectiveStatus = "unverified-source-field" }
quests[28562] = { id = 28562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Westfall!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Leutnant Horatio Laine auf Jansens Hof einzufinden.\n\nWestfall wird von Bettlern und Vertriebenen überrannt, was zu einem massiven Anstieg der Kriminalität geführt hat. Helft bei der Wiederherstellung der öffentlichen Ordnung. Jansens Hof liegt in Westfall, westlich des Walds von Elwynn.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof in Westfall.", completion = "Mord, Grünschnabel. Genau das seht Ihr auf dem Boden vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28563] = { id = 28563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Rotkammgebirge!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Wachhauptmann Parker an der Turmwacht im Rotkammgebirge einzufinden.\n\nHauptmann Parkers Truppen werden von umherstreifenden Gnollen und Orcs angegriffen. Die Bewohner von Seenhain sind in Gefahr. Helft, sie zu schützen. Reist von der Grenze des Walds von Elwynn nach Osten, durch die Drei Ecken im Rotkammgebirge bis nach Turmwacht.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Wachhauptmann Parker an der Turmwacht im Rotkammgebirge.", completion = "Hab gehört, dass Westfall tief im Dreck steckt.\n\n<Parker dreht sich noch nicht einmal zu Euch um.>\n\nNa ja, wir haben hier unsere eigenen Probleme. Seht Ihr die Gnolle da draußen? Die führen doch wieder was im Schilde. Gefällt mir nicht. Gefällt mir ganz und gar nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28564] = { id = 28564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Dämmerwald!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kommandantin Althea Schwarzhaupt in Dunkelhain einzufinden.\n\nDie Wachen der Kommandantin reichen nicht aus, um gleichzeitig gegen umherstreunende Wölfe und Banden wilder Worgen zu kämpfen. Ohne Eure Hilfe werden sie nicht mehr lange durchhalten. Wendet Euch auf der Straße an der Grenze zwischen dem Wald von Elwynn und dem Rotkammgebirge nach Süden, um nach Dunkelhain im Dämmerwald zu gelangen.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Kommandantin Althea Schwarzhaupt in Dunkelhain im Dämmerwald.", completion = "Ihr seid die Hilfe, die wir angefordert haben?\n\n<Althea seufzt.>\n\nDann müsst Ihr uns wohl genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28565] = { id = 28565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Sumpfland!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Gebirgsjäger Rharen in Dun Algaz einzufinden.\n\nDer Kataklysmus und seine Zerstörungen haben wilde Bestien, Orcräuber und grausame Gnolle ins Sumpfland gelockt! Reist von Loch Modan nach Norden durch die Zwergenfestung Dun Algaz, dann gelangt Ihr ins Sumpfland.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Gebirgsjäger Rharen in Dun Algaz.", completion = "In letzter Zeit haben wir kaum Verstärkung erhalten. Eine helfende Hand können wir sehr gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28566] = { id = 28566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dezimierung", description = "<Melisaras Abbild erscheint vor Euch.>\n\nDas Vorauslager der Sturmlanzen befindet sich auf Corrahns Dolch, westlich von Soferas Landspitze. Dringt in das Lager ein und tötet jeden Zwerg, den Ihr seht. Sie müssen lernen, was Furcht bedeutet und es gibt keine bessere Lektion als völlige Dezimierung.\n\nKeine Überlebenden, {name}. Auch ihr Hauptmann - insbesondere ihr Hauptmann - muss sterben.\n\nIch werde Euch kontaktieren.", sourceObjective = "Tötet Hauptmann Eisherz und 12 Soldaten der Sturmlanzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28567] = { id = 28567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Loch Modan!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Pilot Hammerfuß am Südtoraußenposten einzufinden.\n\nSeit der Zerstörung des Steinwerkdamms und der Rückkehr der Kobolde und Troggs sind unsere Gebirgsjäger überfordert. Wir benötigen dringend Verstärkung! Nehmt den Südtorpass im östlichen Dun Morogh, dann gelangt Ihr zum Südtoraußenposten.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Pilot Hammerfuß am Südtoraußenposten in Loch Modan.", completion = "Haben unsere Anführer mein Flehen erhört? Wir verteidigen Loch Modan nur noch mit einer Handvoll Piloten und Gebirgsjägern.", sourceObjectiveStatus = "unverified-source-field" }
quests[28568] = { id = 28568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Der Silberwald!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald zu melden.\n\nMehr denn je wird Eure Hilfe benötigt, um die Heimsuchung durch unsere Feinde in dieser Region zu beenden und den Hafen von Gilneas zu erobern!\n\nIhr müsst nach Süden durch Tirisfal reisen und Euch in den Silberwald begeben, um die Kommandozentrale der Verlassenen zu erreichen. Folgt der Straße im Silberwald nach Süden, bis Ihr die Kommandozentrale der Verlassenen erreicht.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald.", completion = "Sehr gut! Ein neuer Rekrut ist eingetroffen. Es gibt viel zu tun... in der Tat sehr viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[28569] = { id = 28569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kraulsumpfexpress", description = "Ich habe Gerüchte über eine Straße in die Sümpfe des Elends gehört. In diesen mysteriösen Geschichten wird von einem gewundenen Bergpfad gesprochen, der das Rotkammgebirge umgeht und Euch direkt in Kraulsumpf ausspuckt!\n\nWenn Ihr hier nichts mehr zu tun habt, müsst Ihr uns wohl verlassen. Was uns alle sehr traurig stimmen würde. Wenn Ihr geht, dann sprecht mit Sharon Bummhatse in der südöstlichen Ecke der Steppe. Sie wird für Euren Transport sorgen.\n\n<Oralius legt den Kopf schief, so als lausche er etwas.>\n\nWinky? WINKY! NEIN!", sourceObjective = "Sprecht mit Sharon Bummhatse in der südöstlichen Ecke der Brennenden Steppe und erwerbt eine Fahrt im Kraulsumpfexpress zu den Sümpfen des Elends. Sprecht dann mit Handelsbaron Silberkniff in Kraulsumpf.", completion = "Zeit ist Geld, {class}... und ich habe genug von beidem.\n\nWas kann ich für Euch tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[28570] = { id = 28570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kraulsumpfexpress", description = "Ihr seid <ein ziemlich großer/eine ziemlich große:r> {race}, richtig? Seht Euch an... wie erwachsen Ihr geworden seid. Dabei haben wir uns gerade erst kennengelernt!\n\nIch weiß, wie das läuft... bald wisst Ihr nicht mehr, was Ihr auf dem Flammenkamm machen sollt. Ihr versprecht zurückzukehren. Aber das macht Ihr nicht.\n\nKibler kennt das schon.\n\nWenn Ihr geht, dann sprecht mit Sharon Bummhatse in der südöstlichen Ecke der Steppe. Sie wird Euch im Express mitfahren lassen.\n\nWas? Och, das ist nur eine Rakete. Vollkommen sicher.", sourceObjective = "Sprecht mit Sharon Bummhatse in der südöstlichen Ecke der Brennenden Steppe und erwerbt eine Fahrt im Kraulsumpfexpress zu den Sümpfen des Elends. Sprecht dann mit Handelsbaron Silberkniff in Kraulsumpf.", completion = "Zeit ist Geld, {class}... und ich habe genug von beidem.\n\nWas kann ich für Euch tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[28571] = { id = 28571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Vorgebirge des Hügellands!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands zu melden. Die Kriegsmaschine der Verlassenen marschiert unaufhaltsam weiter und sichert der Horde Lordaeron!\n\nFolgt der Straße durch den Silberwald in Richtung Süden und biegt an der Gabelung nach Osten in das Vorgebirge des Hügellands ab. Dort findet ihr die Südwacht.\n\nWeiter, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Meldet Euch bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands.", completion = "Ich habe mich schon gefragt, wann die Verstärkung eintreffen würde. Macht Euch bereit, {name}. Zeit, etwas Gerechtigkeit walten zu lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28572] = { id = 28572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Arathihochland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei der Dunklen Waldläuferin Alina bei Galens Sturz zu melden. Die Streitkräfte der Dunklen Fürstin wollen das Herrschaftsgebiet der Horde vergrößern und die Allianz zurückschlagen. Helft ihnen dabei.\n\nDas Arathihochland liegt östlich des Vorgebirges des Hügellands. Folgt der Straße, die am Thoradinswall vorbeiführt.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei der Dunklen Waldläuferin Alina bei Galens Sturz im Arathihochland.", completion = "Endlich ist die Verstärkung des Kriegshäuptlings eingetroffen. Die Dunkle Fürstin hat für Euch ebenso große Pläne wie für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[28573] = { id = 28573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Arathihochland", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Hauptmann Nials in der Zuflucht einzufinden.\n\nDie Ehre der uralten Burg Stromgarde muss wiederhergestellt werden! Zu lange schon beschmutzen Oger und Kriminelle ihre Straßen. Verlasst das Sumpfland in Richtung Norden und benutzt den Thandolübergang, um nach Arathi zu gelangen. Folgt der Straße bis zur Zuflucht und stellt Euch dem Hauptmann vor.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Hauptmann Nials in der Zuflucht im Arathihochland.", completion = "Ich wünschte, Ihr wärt eine ganze Kompanie, aber es muss auch so gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28574] = { id = 28574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Hinterland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend beim Ältesten Stumpfhauer im Dorf der Bruchhauer zu melden.\n\nDie Zwerge der Wildhämmer haben sich offiziell der Allianz angeschlossen. Das heißt, sie sind nun unsere Feinde. Sie müssen besiegt werden!\n\nBegebt Euch vom Gebirgspass im östlichen Vorgebirge des Hügellands ins Hinterland und begebt Euch zur östlichen Küste. Dort findet Ihr das Dorf der Bruchhauer.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch beim Ältesten Stumpfhauer im Dorf der Bruchhauer im Hinterland.", completion = "Seid Ihr gekommen, um uns gegen die Wildhämmer zu unterstützen? Der Kriegshäuptling weiß, dass das, was hier geschieht, wichtig für die Zukunft der Horde ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28575] = { id = 28575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Westliche Pestländer!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Koltira Todesweber in Andorhal zu melden.\n\nDie Streitkräfte der Allianz rücken auf die zerstörte Stadt Andorhal vor, um sie einzunehmen. Wir müssen ihren Angriff stoppen, bevor sie dort einen Stützpunkt errichten können.\n\nBegebt Euch hinter das Bollwerk am östlichen Rand von Tirisfal und folgt den Straßen in Richtung Südosten nach Andorhal. Schließt Euch dort unseren Streitkräften an.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Koltira Todesweber in Andorhal in den Westlichen Pestländern.", completion = "Mehr kann der Kriegshäuptling nicht entbehren? Keine Sorge, Ihr könnt Euch hier nützlich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28576] = { id = 28576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Westliche Pestländer!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Thassarian in Andorhal einzufinden.\n\nNach unseren ersten Siegen in Andorhal holen die Verlassenen nun zum Gegenschlag aus. Eure Hilfe wird benötigt. Vertreibt die Geißel und die Horde und erobert die verlorene Stadt Andorhal zurück.\n\nIhr erreicht Andorhal, indem Ihr in Richtung Norden durch das Vorgebirge des Hügellands reist und der Straße folgt, die am Zugwindlager vorbeiführt.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.", completion = "Es gibt hier viel zu tun. Wir stehen zwei unbarmherzigen Feinden gegenüber, die uns gnadenlos abschlachten würden, wenn wir unsere Klingen niederlegten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28577] = { id = 28577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Östliche Pestländer!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Fiona am Ostufer des Thondroril zu melden.\n\nDer Argentumkreuzzug hat seine Stellungen in den Pestländern ausgebaut. Eure Hilfe wird benötigt, um diese Siege zu sichern.\n\nÜberquert den Thondroril an der Ostgrenze der Westlichen Pestländer und sucht am anderen Ufer nach Fiona. \n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Fiona am Ostufer des Thondroril in den Östlichen Pestländern.", completion = "Vielleicht könnt Ihr ja helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28578] = { id = 28578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Östliche Pestländer!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Fiona am Ostufer des Thondroril einzufinden.\n\nDer Argentumkreuzzug braucht Eure Hilfe, um die Östlichen Pestländer aus der Gewalt der Geißel zu befreien.\n\nUm die Östlichen Pestländer zu erreichen, müsst Ihr von den Westlichen Pestländern kommend den Thondroril überqueren. Sucht am Ostufer nach Fiona.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Fiona am Ostufer des Thondroril in den Östlichen Pestländern.", completion = "Vielleicht könnt Ihr ja helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28579] = { id = 28579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Ödland!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Gek Düsenschub an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern einzufinden.\n\nDie Schäden, die Todesschwinge angerichtet hat, müssen begutachtet werden, ebenso die Aufstellung der Hordenstreitkräfte im Ödland. Dazu wird Eure Hilfe benötigt.\n\nIm Austausch für Eure Hilfe hat sich Gek bereit erklärt, Euch per Rakete ins Ödland zu bringen. Sucht nach ihm an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Gek Düsenschub an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", completion = "Ihr seid bestimmt hier, um Luntenbrand zu helfen! Ich bringe Euch sofort ins Ödland.", sourceObjectiveStatus = "unverified-source-field" }
quests[28580] = { id = 28580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Ödland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Gek Düsenschub an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern zu melden.\n\nDie Allianz versucht verzweifelt, einen Stützpunkt im Ödland zu errichten. Eure Pflicht ist es, sie zurückzudrängen und Euch ein Bild von den Zerstörungen zu machen, die Todesschwinge angerichtet hat.\n\nGek wird Euch per Rakete ins Ödland befördern. Trefft ihn bei der Kapelle des Hoffnungsvollen Lichts.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Gek Düsenschub an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", completion = "Natürlich kann ich Euch ins Ödland bringen, aber Ihr müsst mir versprechen, dort meinen Kameraden zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28581] = { id = 28581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Sengende Schlucht!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Jack Felsbein am Thoriumvorstoß zu melden.\n\nDie Zerschmetterte Hand meldet, dass die Dunkeleisenzwerge der Sengenden Schlucht sich auf etwas vorzubereiten scheinen. Es ist Eure Pflicht, so viel wie möglich über ihre Machenschaften herauszufinden und sie zu durchkreuzen.\n\nIhr erreicht die Sengende Schlucht, indem Ihr im Ödland der Straße nach Westen folgt.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Jack Felsbein am Thoriumvorstoß in der Sengenden Schlucht.", completion = "In letzter Zeit sind die Dunkeleisenzwerge recht aktiv geworden. Wir beobachten das mit Misstrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28582] = { id = 28582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Sengende Schlucht!", description = "Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Jack Felsbein am Thoriumvorstoß einzufinden.\n\nDer SI:7 meldet, dass die Dunkeleisenzwerge der Sengenden Schlucht anscheinend einen Angriff vorbereiten. Es ist Eure Pflicht, so viel wie möglich über ihre Machenschaften herauszufinden und sie zu durchkreuzen. \n\nIhr erreicht die Sengende Schlucht, indem Ihr im Ödland der Straße nach Westen folgt.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Jack Felsbein am Thoriumvorstoß in der Sengenden Schlucht.", completion = "Wir trauen den Dunkeleisenzwergen ebenfalls nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28583] = { id = 28583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazzwerke", description = "Das neue Schredderdesign ist der Hammer, {name}. Der Hammer! Der nächste Schritt ist der Schutz meines gedanklichen Eigentums. Ich muss Patente ausfüllen, Marken zeichnen und Unterlassungen erklären. Oh, und Bestechung darf auch nicht fehlen!\n\nHier, bringt diesen Patentantrag zu Kapitän Krazz an den Krazzwerken. Er hat die Zerstörung seines Zeppelins überlebt und sucht wahrscheinlich nach neuen Geschäftsmodellen.\n\nDie Krazzwerke befinden sich nördlich von hier auf einem vollkommen sicheren Berggipfel. Auf geht's, <Junge/Mädchen>. Zack zack!", sourceObjective = "Bringt den Patentantrag zu Kapitän Krazz an den Krazzwerken im Schattenhochland.", progress = "Euch kenne ich doch! Ihr wart bei der Hinreise mit mir auf dem Zeppelin.", completion = "Was ist das? Der \"{name}-o-Matik:\" ein Schredder mit integrierter Raketenplattform?\n\nPah! Den hat Arbeitsaufseher Grabbit aus Azshara längst patentieren lassen. Das ist wertlos!\n\nWas ich wirklich brauche, ist eine Maschine, die Zwerge vom Himmel holt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28584] = { id = 28584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Qualitätsarbeit", description = "Hört mal zu, <Chef/Chefin>, wenn es diesen Vollidiot mir gegenüber nicht gäbe, wären die Krazzwerke in einem Topzustand.\n\nDummerweise - und so sehen das alle Beteiligten - hat \"Schickimicki\" Rothmann beschlossen, das Ding auf einem Berggipfel zu bauen! Wer kommt auf so eine Idee?\n\nJetzt gibt es überall Lecks, weil die Ventile defekt sind. Wärt Ihr vielleicht so nett, sie mit dem Dichtungsband zu versiegeln?", sourceObjective = "Versiegelt 10 defekte Ventile mit Dichtungsband.", completion = "Na also. Wollen wir als Nächstes Rothmanns Mund versiegeln?", sourceObjectiveStatus = "unverified-source-field" }
quests[28585] = { id = 28585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poliert" }
quests[28586] = { id = 28586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poolponyrettung", description = "Dieser Idiot mir gegenüber bringt noch alle um!\n\nBrett \"der Bomber\" hat die Krazzwerke am falschen Ort ausgepackt und jetzt sind sie extrem instabil. Bei den Explosionen, die durch die Instabilität entstehen, werden unsere Arbeiter von den Plattformen ins Wasser geschleudert.\n\nWärt Ihr so freundlich hinunterzufliegen und sie mit Hilfe einiger Poolponys zu retten, {name}?", sourceObjective = "Benutzt die Poolponys, um 10 Arbeiter der Krazzwerke, die ins Wasser gefallen sind, zu retten.", completion = "Danke, {name}! Könnten wir doch nur die Krazzwerke stabilisieren, damit unsere Leute nicht mehr von den Plattformen geschleudert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28587] = { id = 28587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe der Frostwölfe", description = "Ich werde die Schlachtpläne der Sturmlanzen studieren und mich auf einen Überfall vorbereiten. Geht ins Alteractal und bittet den Frostwolfklan um Hilfe. Diesem Klan gehört sogar unser ehemaliger Kriegshäuptling Thrall an. Sie müssen uns im Kampf gegen die Zwerge der Sturmlanzen unterstützen! Gemeinsam werden wir die Eindringlinge in den Staub treten und für immer aus Lordaeron vertreiben!\n\nGeht jetzt, {name}. Das Alteractal liegt nordöstlich von Tarrens Mühle. Findet Voggah Todesgriff und sagt ihm, dass die Horde die Hilfe der Frostwölfe benötigt!\n\nLOK'TAR!", sourceObjective = "Sprecht mit Voggah Todesgriff im Alteracgebirge im Vorgebirge des Hügellands.", completion = "Ihr kommt aus Tarrens Mühle? Ihr stinkt nach Tod...", sourceObjectiveStatus = "unverified-source-field" }
quests[28588] = { id = 28588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildhammerplage", description = "Während die beiden Idioten noch darüber streiten, wer hier den Bockmist gebaut hat, müssen wir uns mit einer Invasion der Krazzwerke herumschlagen!\n\nDiese nichtsnutzigen Wildhämmer sind überall. Geht los und säubert die Krazzwerke von dieser übelriechenden, biersaufenden Plage.", sourceObjective = "Tötet 10 Räuber der Wildhämmer.", completion = "Ihr habt ein Händchen fürs Zwergentöten, so viel ist sicher, {name}. Das ist gut.\n\nZwergenmassaker Teil 2, demnächst in diesem Theater.", sourceObjectiveStatus = "unverified-source-field" }
quests[28589] = { id = 28589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niet- und nagelfest", description = "Ihr müsst etwas wegen dieser Sturmkrallen der Wildhämmer unternehmen. Sie reißen uns in Stücke!\n\nWir haben leider keine Munition mehr, deshalb müssen wir improvisieren. Wir haben die Krazzkanonen mit allem möglichen Zeug beladen: Poolponys, Kaja'Coladosen, Essensbehälter, Brennstoffzellen, Reifen... Ihr versteht, was ich meine.\n\nAlles, was nicht niet- und nagelfest ist.\n\nHabt Ihr Lust auf ein paar Zielübungen?", sourceObjective = "Tötet 15 Sturmkrallen der Wildhämmer.", completion = "So ist's richtig! Muss ganz schön erniedrigend sein, von Müll abgeschossen zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28590] = { id = 28590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung", description = "Dieser Allianzabschaum wird endlich kriegen, was er verdient. Außerdem gibt es da etwas, das uns gehört. Ich habe einen Frontalangriff auf Hochstade autorisiert.\n\nGeht an Bord der Himmelsreißer und stürzt Euch in den Kampf. Flick wird Euch alles erklären, wenn Ihr dort eintrefft.", sourceObjective = "Sprecht mit Flick auf der Himmelsreißer, die über Hochstade kreist.", completion = "Gut, dass Ihr hier seid, {name}. Seid Ihr bereit, ein wenig Chaos zu verbreiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[28591] = { id = 28591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Mauer, auf der Lauer", description = "Ihr seht aus, als hättet Ihr Lust auf einen Kampf. Setzt Euch in einen der Geschütztürme und macht die Verteidiger auf der Mauer fertig.\n\nUnd zwar schnell. Am besten, bevor wir als großer Feuerball enden.", sourceObjective = "Vernichtet 80 Scharfschützen von Hochstade, 12 Kanoniere von Hochstade und 4 Kanonen von Hochstade mit dem Geschützturm des Himmelsreißers.", completion = "Die modernisierte goblinische Zerstörungskraft ist erstaunlich, oder? Ich liebe diese Dinger.", sourceObjectiveStatus = "unverified-source-field" }
quests[28592] = { id = 28592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschiedspakete", description = "Flick verfolgt sicherlich einen größeren Plan, aber das wäre kein Angriff, wenn wir nicht wenigstens ein paar explosive Geschenke zurücklassen würden.\n\nGeht runter und bringt etwas von dem Sprengstoff auf dem Boot, am Festungseingang und in einem der nördlichen Türme an. Damit sollten sie eine Weile beschäftigt sein.\n\nWir werden uns ebenfalls zum Boden begeben. Trefft uns am östlichen Turm, wenn Ihr fertig seid.", sourceObjective = "Legt Bomben auf dem Boot, am Festungseingang und in einem der nördlichen Türme.", completion = "Hahah! Tolle Vorstellung.\n\nDamit haben wir sie ordentlich im Hochland willkommen geheißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28593] = { id = 28593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von größter Wichtigkeit", description = "Mit Garroshs Zeppelin ist auch das Induktionssamophlang, das Ihr für uns in Azshara geborgen habt, abgestürzt. Die Allianz hat es irgendwo in dieser Festung versteckt. Krazz will es wiederhaben.\n\nIch tippe auf den Keller der Festung, also beginnt Eure Suche dort. Kehrt zu mir in die Nähe des Ostturms zurück, wenn Ihr es in Händen haltet.", sourceObjective = "Beschafft das Induktionssamophlang.", progress = "Krazz wartet. Trödelt nicht.", completion = "Brillant! Dafür wird Krazz Euch auf Händen tragen. Freut mich für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28594] = { id = 28594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichtmehrganzsohochstade", description = "Geht runter und scheucht dieses Allianzgesindel auf. Egal, welches. Sie sollen wie kopflose Hühner umherlaufen, damit Ihr Euch auf das echte Ziel konzentrieren könnt.\n\nIhr findet uns nahe des Ostturms, wenn Ihr fertig seid.", sourceObjective = "Tötet 10 Verteidiger von Hochstade.", completion = "So macht man das. Kopflose Hühner... Aber eine große Klappe hatten sie schon, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28595] = { id = 28595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazz werkelt!", description = "Das war's. Wir sind fertig. Lasst uns aufbrechen.\n\nMolch hat ein paar Gyrokopter an der Spitze des Turms angebunden. Geht zu ihr und fliegt kurz zurück zu den Krazzwerken. Wir räumen hier auf.", sourceObjective = "Sprecht mit Molch, um zu den Krazzwerken zurückzufliegen. Gebt dort Kapitän Krazz das Induktionssamophlang.", progress = "Sagt mir, dass Ihr es geschafft habt. Ihr schafft es immer. Zeigt mir meine Schönheit!", completion = "Darauf habe ich mich die ganze Zeit gefreut! Mit dieser Schönheit hebt die Flotte schon bald wieder ab.\n\nIhr wisst genau, was ich mag, {name}. Und ich weiß, was Ihr mögt - nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[28596] = { id = 28596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Hochstade!", description = "Willkommen im Hochland, <Soldat/Soldatin>. Ihr kommt gerade rechtzeitig.\n\nDie Hordentruppen haben gerade mit ihrem Luftangriff begonnen. Unternehmt etwas dagegen. Werdet sie los!", sourceObjective = "Tötet 10 Angreifer der Horde in Hochstade.", progress = "Ihr müsst noch ein paar mehr töten, Soldat.", completion = "Das sieht schon besser aus. Den Rest kehren wir von hier aus der Stadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28597] = { id = 28597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenfutter", description = "Har! Wir können direkt loslegen, {name}. Hochstade hat anscheinend ein echt großes Zeppelinproblem. Das Luftschiff zerlegt die Mauern.\n\nIch habe eine Idee, die so dämlich ist, dass man sie genial nennen könnte. Ich brauche nur etwas Kanonenpulver.\n\nSammelt alles Pulver ein, das ihr in Hochstade finden könnt und trefft mich im Handelsviertel!", sourceObjective = "Sammelt 10 Säcke mit Kanonenpulver.", progress = "Ich brauche mehr Pulver! Bringt mir mehr Pulver! Mehr mehr mehr!", completion = "Jawoll, das reicht.\n\n<Flintlocke stopft sich etwas von dem Pulver in den Mund.>\n\nOhhh, frisch. Berauschend. Feinstes Korn aus dem Rotkammgebirge mit einem Hauch Westfallschwefel und einem milden Nachgeschmack. Hochstade kriegt nur das Beste.", sourceObjectiveStatus = "unverified-source-field" }
quests[28598] = { id = 28598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hohes Ziel", description = "Seht mal, {name}. Ich hab' die größte Waffe in Hochstade! Wir werden 'ne Taktik ausprobieren, die mein Papa von seinem Papa gelernt hat und der von seinem Papa, kurz bevor er in die Luft flog.\n\nSie nennt sich \"{class}-Schuss.\"\n\n<Ein/Eine:c> {class} muss in 'ne riesige Kanone und dann – hey, entspannt Euch. Das haut meistens hin.\n\nNehmt den Sprengstoff und wartet neben mir. Wenn das Luftschiffchen wieder vorbeikommt, schieße ich Euch aufs Deck. Bringt den Sprengstoff in seinem Rumpf an und... keine Ahnung, denkt Euch was aus.", sourceObjective = "Wartet, bis Euch Fargo Flintlocke auf den Zeppelin gebracht hat und bringt seine Sprengladung in der unteren Kabine an.", progress = "Es gibt kein Problem, das man nicht mit einer Bombe lösen könnte.", completion = "<Flintlocke wischt sich die Tränen aus den Augen.>\n\nOh, {name}. {name}!\n\nDas... war wunderschön.", sourceObjectiveStatus = "unverified-source-field" }
quests[28599] = { id = 28599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurdran wartet", description = "Der Angriff hat anscheinend aufgehört, {name}. Eigentlich schade, sonst hätten wir die {class}-Rakete noch ausprobieren können.\n\nWie dem auch sei, Kurdran Wildhammer steht oben auf der Festung. Er will Euch garantiert als <Helden/Heldin> feiern. Habt Ihr auch verdient! Redet mal mit ihm!\n\nIch gehe schon mal vor und erkunde den Strand.", sourceObjective = "Sprecht mit Kurdran Wildhammer in der Burg Hochstade im Schattenhochland.", completion = "Ihr wurdet vom König persönlich geschickt? Es freut mich, dass Sturmwind sicher ist.\n\nIch hatte eigentlich weitere Truppen erwartet, aber so wie man hört, wurde die Allianzflotte auf dem Weg hierher von der Horde angegriffen. Sie haben alles gegeben, trotzdem wurde ihre Flotte zerschossen.\n\nWenn wir hier im Hochland Fortschritte machen wollen, werden wir die Hilfe von Helden wie Euch brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28600] = { id = 28600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Loyalität", description = "Ich habe keine Entscheidungsgewalt bei solchen Angelegenheiten. Ihr müsst mit unserem Anführer Drek'Thar sprechen. Ich habe Eure Ankunft in Burg Frostwolf bereits angekündigt. Drek'Thar wird sich persönlich mit Euch treffen.", sourceObjective = "Sprecht mit Drek'Thar.", completion = "<Oberster Kriegsfürst Cromush wird blass.>\n\nSIE LASSEN UNS IM STICH? SIE LASSEN DIE HORDE IM STICH? Das kann nicht sein!\n\nIch...\n\n<Cromush geht auf ein Knie.>\n\nIch... ICH WERDE NICHT AUFGEBEN. Wir werden das auch ohne ihre Hilfe schaffen. Zur Hölle mit den Frostwölfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28601] = { id = 28601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alter Kahn" }
quests[28602] = { id = 28602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid vorbereitet", description = "Jeder Abenteurer, der etwas auf sich hält, weiß, dass man niemals einen Fuß in eine Höhle, ein Verlies, eine Krypta oder eine Grabstätte setzt, ohne ausreichend Seil dabeizuhaben... nicht wahr?\n\nNun, meine Seile waren in dem Wagen voller Sprengstoff, den Ihr in die Luft gejagt habt.\n\nWieso seht Ihr Euch nicht mal hier um, ob Ihr noch etwas findet.", sourceObjective = "Sammelt 6 Stücke Seil.", progress = "Was macht die Suche?", completion = "Irgendwie habe ich das Gefühl, ich werde es brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28603] = { id = 28603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration", description = "Hier ist Eure nächste Mission: Reist nach Westen zur Landzunge und infiltriert das Übungsgelände der Sturmlanzen. Dort gibt es zwar hunderte Sturmlanzen in der Ausbildung, aber eine meiner Banshees wird Euch so tarnen, dass Ihr wie einer der Menschen ausseht, die vor kurzem gefangen genommen wurden. Dann könnt Ihr Euch frei zwischen den Feinden bewegen.\n\nBetretet die Landzunge und sucht nach den Ausbildern der Sturmlanzen. Findet sie und bringt sie dazu, Euch anzugreifen! Wenn sie das tun, bringt Ihr sie um. Ohne ihre Ausbilder werden sie keine weiteren Soldaten mehr unterweisen können!", sourceObjective = "Tötet Ausbilder Rufus, Ausbildungsoffizier Magnus und Hauptmann Rattenbart.", sourceObjectiveStatus = "unverified-source-field" }
quests[28604] = { id = 28604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täuschung und Betrug", description = "Solange ich an Eurer Seite bleibe, werden die Feinde Euch für <einen/eine> der ihren halten. Eure neue Menschlichkeit sollte Euch allerdings nicht dazu verleiten, draufgängerisch zu werden. Wenn Ihr Aufmerksamkeit erregt, werden die Zwerge misstrauisch und Euch wahrscheinlich angreifen!\n\nDoch ich habe einen Plan. Nehmt dieses Fass mit vergiftetem Wasser und stillt damit den Durst von müden Lehrlingen der Sturmlanzen. Wenn sie davon trinken, werden sie todkrank und schließlich an dem Gift sterben.", sourceObjective = "Vergiftet 30 Lehrlinge der Sturmlanzen mit dem Wasserfass.", progress = "Täuschung und Betrug - dies sind Eure Werkzeuge!", completion = "Sie werden nicht sofort sterben, aber sterben WERDEN sie! Wenn sie erkennen, wer für den Tod ihrer Soldaten verantwortlich ist, werdet Ihr längst weg sein - ein Phantom des Todes!", sourceObjectiveStatus = "unverified-source-field" }
quests[28605] = { id = 28605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschung", description = "<Melisaras Gedanken mischen sich in Eure eigenen.>\n\nEure letzte Aufgabe wird ein Angriff auf die Belagerungstechniker von Gavins Landspitze, westlich der Landzunge, sein. Brecht zum letzten Finger auf und vernichtet die Zwergen- und Gnomeningenieure, die für den Bau und die Befestigung der Kriegsmaschinen der Sturmlanzen verantwortlich sind. Vergesst nicht, Cromushs letzte Hosentaschenbombe zu platzieren.", sourceObjective = "Tötet 10 Ingenieure der Sturmlanzen.", completion = "Die Streitkräfte der Sturmlanzen sind geschwächt. Es ist Zeit für die Sprengung!", sourceObjectiveStatus = "unverified-source-field" }
quests[28606] = { id = 28606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel für den Hot Rod" }
quests[28607] = { id = 28607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel für den Hot Rod" }
quests[28608] = { id = 28608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengrab", description = "Es freut mich, dass Ihr wieder auf den Beinen seid, {name}. Ihr habt Euch gut gehalten, obwohl Ihr so lange tot wart!\n\nAndere hatten weniger Glück. Würdet Ihr meine Balsamierungsflüssigkeit und etwas Faden holen, damit ich diese Leichen zusammenflicken kann? Beides werdet Ihr im Schattengrab, dem Gebäude direkt hinter mir, finden.\n\nDarnell wird Euch begleiten. Er kennt den Weg.", sourceObjective = "Holt zähe Balsamierungsflüssigkeit und Leichenflickerzwirn aus dem Schattengrab in Todesend.", progress = "Ihr findet die Gegenstände im Schattengrab. Ich glaube, ich habe sie auf meinem Arbeitstisch liegen gelassen.", completion = "Genau die brauche ich. Ihr werdet für die Verlassenen von Nutzen sein, {name}.\n\nMan sagt, dass Ihr in Eurem letzten Leben ein ziemlich guter {class} wart. Vielleicht sollte ich Euch eine etwas aufregendere Aufgabe geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28609] = { id = 28609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerschläge", description = "Seit Wochen streiten wir drei uns darüber, wessen Waffen die besten sind.\n\nNiemand soll behaupten, dass meine Streitkolben zweitklassig wären. Kilrams Äxte und Serils Schwerter kommen niemals an die Stärke meiner Waffe heran.\n\nDer Streit geht mir auf die Nerven. Ich werde den beiden mit einer kleinen Vorführung beweisen, dass ich recht habe. Würdet Ihr bitte nach draußen gehen und Deez Felsklau sagen, dass ich den größten Felsbrocken brauche, den er auftreiben kann?", sourceObjective = "Sprecht mit Deez Felsklau.", completion = "Lilith möchte also, dass ich einen Felsbrocken in das Observatorium bringe? Das ist mein Geschäft: kompakte Waren. Normalerweise kommen Einzelkunden nicht zu mir, aber ich werde bestimmt keine Fragen stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28610] = { id = 28610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollendes Geröll", description = "Ihr könnt den Felsbrocken mit meinem patentierten Fels-in-der-Kiste hineinbringen! Normalerweise würde ich ihn Euch einfach verkaufen, aber mir sind die Materialien ausgegangen.\n\nAuf dem Gipfel südlich der Stadt sind Erdelementare aufgetaucht. Die sind eine gute Quelle für Geröll. Bringt mir genug davon, dann bezahle ich Euch für die Aufstockung meines Lagers und lege noch einen Fels-in-der-Kiste dazu. Umsonst!", sourceObjective = "Beschafft 6 hochwertige Geröllbrocken von Frostsplitterrumplern.", progress = "Habt Ihr das Geröll?", completion = "Das sollte reichen! Hier ist Eure Bezahlung, wie versprochen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28611] = { id = 28611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ritual der Entweiher", description = "Ah, ich sehe bereits klarer, {name}.\n\nEs ist richtig, den bösartigen Neferset zu misstrauen. Ich spüre bereits, dass sie hinter den Kräften stecken, die den Fluss verderben.\n\nTaucht noch einmal hinab und findet die Finstergrundhöhle. Ihr werdet sehen, dass die Neferset dort ein dunkles Ritual der Verderbnis ausüben.\n\nHaltet sie auf, damit der Fluss wieder rein wird.", sourceObjective = "Unterbrecht das Ritual der Neferset in der Finstergrundhöhle.", completion = "Das Wasser des Flusses ist fast wieder klar. Unsere prophetischen Visionen werden bald zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28612] = { id = 28612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harrison Jones und der Tempel von Uldum", description = "Wir haben viel durchgemacht, aber das scheint sich jetzt endlich auszuzahlen!\n\nUns trennen nur noch wenige Schritte von der Lade... Ich habe die Chiffren studiert, um sie zu enthüllen... Schnottz hält uns für tot.\n\nIch glaube, wir kriegen das doch noch hin!", sourceObjective = "Erbeutet die Lade der Verheißung.", completion = "Aber Ihr habt Glück, denn dieser Zwerg hat noch ein oder zwei Asse im Ärmel!\n\nHeehee! ...Ihr hättet Euren Gesichtsausdruck sehen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28613] = { id = 28613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sehen uns auf der Anderen Seite!", description = "Also gut, {name}. Wir haben uns ein wenig Zeit verschafft, aber die dürfen wir nicht vertrödeln.\n\nFolgt mir!", sourceObjective = "Sprecht mit Harrison Jones auf dem Aufstieg des Schöpfers in Uldum.", completion = "So weit, so gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[28614] = { id = 28614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärserker", description = "Die Abwesenheit von Oberhäuptling Winterfell hat den Zorn der Winterfelle nicht gerade gemindert. In der Zwischenzeit hat ihr größter Krieger enorme Macht an sich gerissen.\n\nGrolnar der Berserker haust in der Höhle ganz oben im Lager der Winterfelle. In ihm steckt genug verderbtes Feuerwasser, um zehn normale Furbolgs zu töten.\n\nEr ist zu einer aufgeblähten, schrecklichen Bestie geworden! Unsere Krieger werden mit ihm nicht fertig... seid Ihr stark genug, um ihn zu besiegen, {class}?", sourceObjective = "Tötet Grolnar den Berserker.", completion = "Eure Taten beweisen mir und der Holzschlundfeste wieder einmal, was für ein mächtiger Krieger Ihr seid!\n\nHoffentlich haben wir die Winterfelle damit endgültig besiegt...", sourceObjectiveStatus = "unverified-source-field" }
quests[28615] = { id = 28615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdwiderstand", description = "Trotz ihres Wahnsinns und ihrer Verderbnis klammern sich die Winterfelle mit letzter Kraft an ihre schamanischen Kräfte. Dass sie die Macht der Elemente benutzen, um meinem Stamm und anderen Unschuldigen Schaden zuzufügen, verstört mich.\n\nWir werden ihre Totems gegen sie wenden! Nehmt mein Totem mit ins Lager der Winterfelle. Setzt seine Macht aus der Ferne bei den Totems der Winterfelle ein, dann wird der Zorn der Erde über alle kommen, die sich in der Nähe aufhalten!\n\nDass Ihr einen Sicherheitsabstand einhalten solltet, muss ich wohl nicht erwähnen!", sourceObjective = "Überladet 4 Erdtotems der Winterfelle mit Tanrirs überladenem Totem.", completion = "Mögen die Winterfelle nie wieder die Holzschlundfeste bedrohen. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28616] = { id = 28616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmlanzenapokalypse", description = "Bevor wir fortfahren, möchte ich um eine Schweigeminute für unseren gefallenen Bruder Orkus bitten, ohne den wir von den Sturmlanzen vernichtet worden wären. Das ist für Euch, Bruder!\n\n<Cromush geht auf ein Knie.>\n\nNun, {name}, glaubt nicht, dass ich Euren Anteil an all dem vergessen hätte! Deshalb gewähre ich Euch die Ehre, die goblinischen Hosentaschenbomben zu zünden.\n\nSeid Ihr bereit? FÜR DIE HORDE!", sourceObjective = "Werdet Zeuge der Sturmlanzenapokalypse.", completion = "Die Finger sind zerstört, die Hand ist zerschlagen. Jetzt werden sich die Sturmlanzen in ihre Höhle im Alteractal zurückziehen müssen.\n\n<Cromush spuckt aus.>\n\nKriegshäuptling Höllschrei wird von Eurem Mut erfahren, {name}.\n\nUnd Ihr könnt sicher sein, dass wir den Verrat des Frostwolfklans ebenfalls erwähnen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[28617] = { id = 28617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blumenkinder", description = "Ihr habt bereits gelernt, wie man die Speier verwendet, aber wusstet Ihr, dass alles schneller wächst, wenn man Sonnenblumen benutzt? Wir werden ein paar Sonnenblumen heranziehen und einige Speier pflanzen und damit Aufseher Stillwassers verrückte Monstrositäten aufhalten.\n\nLos!", sourceObjective = "Überlebt eine riesige Zombiewelle.", completion = "Ich glaube, das war erst der Anfang, Kumpel! NEUE WELLE!", sourceObjectiveStatus = "unverified-source-field" }
quests[28618] = { id = 28618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felslieferung", description = "Bitte sehr, wie versprochen! Ein Fels in einer Kiste.\n\nDarum hat Lilith doch gebeten, oder? Sie ist meine einzige Kundin!", sourceObjective = "Gebt einen Fels in einer Kiste bei Lilith der Lieblichen in der Ewigen Warte ab.", progress = "Oh, Ihr schon wieder. Wo ist der Fels?", completion = "Ah, Ihr habt tatsächlich einen Fels mitgebracht! Das überrascht mich etwas.\n\nTretet zurück und werdet Zeuge allerhöchster Handwerkskunst.", sourceObjectiveStatus = "unverified-source-field" }
quests[28619] = { id = 28619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Arathihochland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei der Dunklen Waldläuferin Alina bei Galens Sturz zu melden. Die Streitkräfte der Dunklen Fürstin wollen das Herrschaftsgebiet der Horde vergrößern und die Allianz zurückschlagen. Helft ihnen dabei.\n\nDas Arathihochland liegt östlich des Vorgebirges des Hügellands. Folgt der Straße, die am Thoradinswall vorbeiführt.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei der Dunklen Waldläuferin Alina bei Galens Sturz im Arathihochland.", completion = "Endlich ist die Verstärkung des Kriegshäuptlings eingetroffen. Die Dunkle Fürstin hat für Euch ebenso große Pläne wie für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[28620] = { id = 28620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ostwachtturm", description = "In unserem Außenposten im Südosten gibt es einige Probleme. Mehr weiß ich auch nicht, nur... nun, ich werde Euch einfach aus dem letzten Brief vorlesen:\n\n\"Die Orcs werden bockig. Schickt Hilfe, sonst lasse ich sie mit Schilfrohr schlagen.\"\n\nDas ist alles. Der Brief stammt von unserem Chefpsylosophen Nils Bierwurz. Und nein, ich weiß auch nicht, was das heißen soll. Würdet Ihr bitte zum Ostwachttum reisen und herausfinden, was er braucht? Ich halte diese kryptischen Briefe nicht mehr aus!\n\nWendet Euch nach Süden und folgt dann der Straße nach Osten.", sourceObjective = "Sprecht mit Nils Bierwurz am Ostwachttum im Vorgebirge des Hügellands.", completion = "Endlich schickt dieser Schwachkopf Hilfe! Diesen beiden Orcs ist nicht mehr zu helfen. Sie leiden unter etwas, das ich \"Durnholdesyndrom\" nenne. Sie waren so lange eingekerkert, dass sie begonnen haben, Zuneigung für ihre Wärter zu empfinden. Sie sitzen mit ihren großen Eisenkugeln auf meinem Sofa und weinen.\n\nHoffentlich werdet Ihr Euch als nützlicher erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28621] = { id = 28621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt das Baby in die Wiege!", description = "Ach!\n\nIhr und Junior habt Euch ja schön viel Zeit gelassen, oder!?\n\n<Bier trinken/Händchen halten>, die Aussicht genießen - liege ich richtig?\n\nBrecht Euch nicht die Hand, wenn Ihr Euch auf die Schulter klopft. Die richtige Arbeit kommt erst noch!\n\nIn diesem alten Artefakt steckt mehr, als es den Anschein hat. Um seine Geheimnisse zu ergründen, müssen wir es zur Wiege der Uralten bringen!\n\nAber wie stellen wir das am besten an?\n\nVielleicht fällt Junior ja was Schlaues ein.", sourceObjective = "Sprecht mit Harrison Jones beim Tempel von Uldum.", completion = "Natürlich habe ich einen Plan, wie wir die Lade transportieren.\n\nVielleicht wird dieser alte Kautz ja eines Tages lernen, mir zu vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28622] = { id = 28622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein, zwei, nein, drei Signalleuchtfeuer", description = "Ich wollte die Lade eigentlich zur Untersuchung in mein Labor bringen, aber anscheinend hat Brann hier andere Pläne.\n\nEr meint, zu wissen, wie wir Todesschwinges Pläne hier in Uldum durchkreuzen können.\n\nMein Kumpel Jock wartet nur auf unser Signal, um mit dem Transport zu beginnen.\n\nNehmt diese Signalleuchtfeuer und stellt sie um den Tempel herum auf, damit er weiß, dass wir bereit sind.", sourceObjective = "Benutzt die Signalleuchtfeuer beim Tempel von Uldum.", completion = "Gute Arbeit, mein Freund.\n\nAnscheinend haben alle die Reise überstanden.\n\nSo langsam verstehe ich, warum Ihr Junior begleiten dürft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28623] = { id = 28623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Westen", description = "Unsere Arbeit hier ist getan, {name}. Obwohl alles gegen uns sprach, konnten wir einen Vorstoß der Neferset auf Nahom verhindern.\n\nWir sollten uns den Streitkräften anschließen, die den Kampf nach Westen tragen, sonst streichen sie all den Ruhm allein ein.\n\nWahrscheinlich haben sie schon die Randgebiete von Neferset erreicht.", sourceObjective = "Meldet Euch bei König Phaoris in den Außenbezirken von Neferset in Uldum.", completion = "Ihr seid gerade rechtzeitig eingetroffen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28624] = { id = 28624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kilrams Prahlerei", description = "Pah! Primitiv und schwerfällig, was anderes kann ich dazu nicht sagen!\n\nStärke ist nicht alles. Meine Äxte sind so stark wie Liliths Streitkolben, aber so scharf, dass ich einen Baum mit einem Schlag fällen kann!\n\nIhr habt es gehört. Ein Schlag! Ich werde es Euch vor allen hier beweisen. Geht zu Deez. Er soll einen Baum herbringen!", sourceObjective = "Sprecht mit Deez Felsklau.", completion = "Jetzt wollen sie einen Baum? Mal sehen, was ich habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28625] = { id = 28625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baum fällt!", description = "Ich handle viel mit Brettern, aber komplette Bäume? Das wird selten verlangt. Ebenso wie Felsen.\n\nVielleicht könnt Ihr mir ja noch einen Gefallen erweisen. Westlich der Stadt gibt es einen Hain, von dem aus man den Kel'Therilsee sehen kann. Ich weiß nicht, ob es an den Geistern liegt oder an all dem magischen Elfenmüll, der überall herumliegt, aber in letzter Zeit tauchen dort Treants und Peitscher auf.\n\nSeit sie dort sind, macht es keinen Spaß mehr, Holz zu fällen, also warum fällt Ihr sie nicht stattdessen? Bringt mir das Holz der Treants.", sourceObjective = "Beschafft 10 Stücke frischgeschlagenes Frostholz von Frostlaubtreants.", progress = "Zeigt mir das Holz.", completion = "Das ist eine ordentliche Ladung. Vielleicht sollten wir anfangen, Treants anstatt Bäumen zu pflanzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28626] = { id = 28626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baumlieferung", description = "Bitte sehr, ein Wunderwuchs-Instantbaum, hergestellt mit 80% natürlicher Zutaten!\n\nKeine Wurzel, keine Nuss, kein Verdruss. Gebt ihn Kilram und sorgt dafür, dass er ein ordentliches Stück zurücktritt, bevor er ihn benutzt.", sourceObjective = "Bringt den Wunderwuchs-Instantbaum zu Kilram im Gasthaus der Ewigen Warte.", progress = "Zack zack!", completion = "Also gut! Bleibt zurück und seht Euch an, was eine Waffe von gehobener Qualität anrichten kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[28627] = { id = 28627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serils Prahlerei", description = "Wilde und Amateure.\n\nEs spielt keine Rolle, wie scharf oder schwer eine Waffe ist, wenn man damit nur herumfuchteln kann wie ein Oger. Ich könnte versuchen, Dinge wie Raffinesse und Geschwindigkeit, Balance und Kontrolle zu erklären... aber diese Narren werden das nur verstehen, wenn ich es ihnen zeige.\n\nSagt Deez, dass wir noch eine Lieferung von ihm benötigen. Ich brauche einen Eisblock.", sourceObjective = "Sprecht mit Deez Felsklau.", completion = "Oh, Ihr schon wieder! Was für eine Überraschung!", sourceObjectiveStatus = "unverified-source-field" }
quests[28628] = { id = 28628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eislieferung", description = "Also gut, ein 100% reiner Soforteisblock von höchster Qualität!\n\nIch habe versucht, die Kunden eine Weile lang zum Schutz zu verkaufen. Ihr wisst schon, wie dieser Trick, den Magier drauf haben? Die Sache mit dem \"Atmen\" habe ich nur nie hinbekommen.", sourceObjective = "Bringt den Soforteisblock zu Seril Geißelbann in der Ewigen Warte.", progress = "Ah, da seid Ihr ja!", completion = "Perfekt. Jetzt werdet Ihr sehen, worauf es bei einer Waffe ankommt... Raffinesse.", sourceObjectiveStatus = "unverified-source-field" }
quests[28629] = { id = 28629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind wir endlich da, Yeti?", description = "Meine Freunde haben immerzu tolle Ideen. Ich habe nie das Gefühl gehabt, mit ihnen mithalten zu können... bis heute! Gerade habe ich die Pläne für etwas Großes angefertigt! Wenn Ihr versprecht, es nicht zu erzählen, weihe ich Euch in das Geheimnis ein... \n\nIch werde einen mechanischen Yeti herstellen! Meine Freunde werden ganz bestimmt durchdrehen, wenn sie ihn sehen, aber wenn sie darüber hinweg sind, bin ich mir sicher, dass sie beeindruckt sein werden!\n\nIch brauche dickes Yetifell von Eisdistelyetis. Ihr werdet sie südöstlich von hier in den Eisdistelbergen finden.", sourceObjective = "Erbeutet 10 dicke Yetifelle von Eisdistelyetis.", progress = "Für den Anfang habe ich mehr als genug. Bitte bringt mir die Felle so schnell Ihr könnt!", completion = "Diese Felle sind perfekt, {name}. Damit haben wir einen guten Anfang!", sourceObjectiveStatus = "unverified-source-field" }
quests[28630] = { id = 28630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo Drei", description = "Oben in den Eisdistelbergen sind zahlreiche Goblins verschwunden. Beinahe wäre mir das auch passiert!\n\nIch bin auf die Idee gekommen, einen Sensor zu installieren, der uns warnen sollte, wenn die Yetis sich der Ewigen Warte nähern. Natürlich funktioniert der auch nicht. Die Hügel sind voller Yetis, aber ich habe noch keinen Laut von ihm gehört.\n\nWürdet Ihr ihn für mich überprüfen? Vielleicht lässt er sich reparieren. Echo Drei steht südöstlich von hier, am Rand der Eisdistelberge. Fragt nicht, was aus Echo Eins und Zwei geworden ist.", sourceObjective = "Findet Echo Drei.", completion = "Ein Teil der Maschine bewegt sich noch, aber als Ihr genauer hinseht, bemerkt Ihr, dass sie stark beschädigt ist. Das Metall ist verbogen und aufgerissen. Riesige Fußabdrücke sind rund herum im Schnee zu sehen.\n\nUnd es klingt, als nähere sich etwas in diesem Moment...", sourceObjectiveStatus = "unverified-source-field" }
quests[28631] = { id = 28631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekte Hörner", description = "Ich kann doch keinen Yeti ohne Hörner machen!\n\nSeit einer Ewigkeit suche ich schon nach den perfekten Hörnern... aber die, die ich finde, sind nicht gut genug! Vor ein paar Tagen habe ich jedoch den größten Yeti in ganz Winterquell gesehen.\n\nIch nenne ihn Eisklatscher. Seine Hörner wären genau richtig! Er lauert ganz hinten in der Höhle auf dem östlichen Kamm der Eisdistelberge.\n\nBringt mir seine Hörner... aber vergesst nicht, Echo Drei auf dem Weg zu überprüfen!", sourceObjective = "Erbeutet Eisklatschers makellose Hörner.", progress = "Sind sie perfekt? Das hoffe ich!", completion = "Ich kann es gar nicht erwarten, das meinen Freunden zu zeigen! Also, wartet einen Moment, während ich die hier befestige... \n\nPerfect!", sourceObjectiveStatus = "unverified-source-field" }
quests[28632] = { id = 28632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch von den Hügeln", description = "Dieses Mal soll es Eis sein? Klar, was auch sonst. Ich habe gute und schlechte Nachrichten für Euch.\n\nDie guten: Es gibt reines, festes Eis in der Höhle in den Eisdistelbergen, östlich der Ewigen Warte. Die schlechten: Leider gibt es da auch jede Menge grausamer Yetis.\n\nAber wenn Ihr mit Yetis fertigwerdet, ist das ein Kinderspiel! Geht einfach zu den größeren Brocken und zerschlagt sie mit Eurer Waffe. Bringt alles hierher und überlasst mir den Rest.", sourceObjective = "Besorgt 7 Stücke reines Gletschereis aus der Höhle in den Eisdistelbergen.", progress = "Oh, Ihr seid zurück! Wie lief es mit den Yetis?", completion = "Nicht schlecht! Dann hoffen wir mal, dass sie als Nächstes nicht um Lava bitten, richtig?", sourceObjectiveStatus = "unverified-source-field" }
quests[28633] = { id = 28633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lade der Verheißung", description = "Ich bin mir nicht sicher, was uns hier erwartet, also haltet die Augen offen.\n\nDiese Codes sollten uns den wahren Zweck der Lade enthüllen und uns Werkzeuge in die Hand geben, mit denen wir die Pläne, die Todesschwinge für Uldum hat, endgültig durchkreuzen können!\n\nBleibt zurück!", sourceObjective = "Gebt Brann Bronzebart den Inhalt der Lade der Verheißung.", progress = "Also dann.\n\nSeht Euch das an!?", completion = "Natürlich! Ich hatte geahnt, dass wir das finden würden.\n\nAllerdings überraschen mich die organischen Transformationen doch ein wenig.\n\nIn diesem alten Relikt steckt mehr, als ich zu hoffen gewagt hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[28634] = { id = 28634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrottung", description = "Eulenbestien... Seelenlose, gefiederte Monstrositäten, die den dunkelsten Tiefen des Wirbelnden Nethers entstiegen sind, um den Schwachen nachzustellen.\n\n<Nils zeigt auf die Wälder, die den Ostwachttum umgeben.>\n\nSie kreisen uns ein und sie planen einen Angriff - ich spüre es. Haltet sie auf, bevor sie eine Strategie entwickeln.\n\nGeht in den Wald und tötet jede Eulenbestie, die Ihr seht. KEINE DARF ÜBERLEBEN!", sourceObjective = "Tötet 12 tobende Eulenbestien.", completion = "Das Jucken hat aufgehört - erst einmal - aber sie werden zurückkehren.\n\nOh ja, das werden sie...", sourceObjectiveStatus = "unverified-source-field" }
quests[28635] = { id = 28635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespenstischer Hügellandhof", description = "Der Kampf um Dun Garok war der blutigste in der Geschichte der Hügellandschlachten. Die Zwerge standen vor einer zehnfachen Übermacht, kämpften aber bis zum bitteren Ende. Sie alle starben bei der Verteidigung dieses Stück Landes.\n\nNun heißt es, dass es dort spukt. Niemand traut sich heran! Dummerweise habe ich den Befehl erhalten, Dun Garok für eine Besiedlung vorzubereiten.\n\nWürdet Ihr mir den Gefallen erweisen, nach Dun Garok zu gehen und nach Beweisen für diese Geister zu suchen? Dun Garok liegt weit im Südosten.", sourceObjective = "Sucht in Dun Garok nach Beweisen für Geister.", completion = "Geister? Das kann man wohl sagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28636] = { id = 28636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schweigen der Zwerge", description = "Die Geister meiner Soldaten spuken in diesem Fort, <Junge/Mädchen>. Ihre Seelen sind an diesen Ort gebunden. Selbst im Tod kämpfen sie weiter für ihn. Traurig.\n\nMacht ihrem Leid ein Ende, dann könnt Ihr den Sieg Eures Volks vielleicht genießen.", sourceObjective = "Tötet 10 Geister von Dun Garok.", completion = "Selbst nach dem Tod kämpfen sie noch für ihr Land - so wie die Verlassenen. Ich werde der Kommandozentrale melden, dass Dun Garok unbewohnbar ist. Sie sollen behalten, was ihnen so am Herzen liegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28637] = { id = 28637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenhunger", description = "Habt Ihr jemals Bärenfleisch probieren dürfen? In Gilneas hatte ich nie Gelegenheit dazu, aber die Bären hier sind wahre Delikatessen.\n\nDas Fleisch der Splitterzahnbären, die südlich von hier umherziehen, ist durch die Kälte gut mit Fett durchsetzt. Ich habe sie schon selbst gejagt, was ein ziemlicher Jux ist, aber noch lieber esse ich sie!\n\nWarum probiert Ihr die Jagd nicht einmal aus? Konzentriert Euch auf die Splitterzahnbären mit weißem Fell. Der Hauptmann wird alle, die Ihr tötet, hierher bringen.", sourceObjective = "Tötet 15 Splitterzahnbären.", sourceObjectiveStatus = "unverified-source-field" }
quests[28638] = { id = 28638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eulen sind die besten", description = "Ich habe mein ganzes Leben lang Eulen gegessen. Eulen schmecken gut, mein Freund Jez findet das auch. Ich habe ihm als erster vorgeschlagen, Eule zu verkaufen!\n\nDer hochwohlgeborene Worgen da vorn behauptet, Bär schmecke besser, aber ignoriert ihn einfach. Jagt erst einmal selbst ein paar Eulen. Südlich von hier gibt es jede Menge. Haltet Euch erstmal an die grauen und meldet Euch bei mir mit dem kleinen Sprechgerät, das Jez Euch gegeben hat, wenn Ihr ein paar zusammen habt.", sourceObjective = "Tötet 15 Winterquelleulen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28639] = { id = 28639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursius", description = "Es heißt ja, man ist, was man isst. Ich weiß nicht, ob ich das glauben soll, aber wenn es stimmt... Also dann will ich die stärkste Kreatur essen, die ich finden kann.\n\nUrsius ist der größte Bär in ganz Winterquell. Er frisst als erster, wenn sein Rudel Splitterzähne eine Schimäre oder einen Eulenbär tötet. Ihm gehört die gemütlichste Höhle im Land der Splitterzähne. Und er hat... bemerkenswerten Einfluss auf die Weibchen der Splitterzähne.\n\nSo ein Bär gefällt mir.\n\nIch will ihn essen.\n\nSeine Höhle liegt in der Nähe der Raufer. Viel Glück!", sourceObjective = "Tötet Ursius.", completion = "Ursius schmeckt... nicht gerade köstlich. Sein Geschmack erinnert mich an eine Mischung aus Tannenzapfen und saurer Milch, nur... öliger.\n\nUnd Ihr seid sicher, dass das Ursius ist? Der große Bär? In der Höhle?\n\nDas ist furchtbar. Das Fleisch schmeckt so, als habe man es in Urin eingelegt.\n\nIch fühle mich nicht stärker.\n\nBah. Das ist wirklich übel. Wollt Ihr mal probieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[28640] = { id = 28640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frische Frostsäbler", description = "Riecht das nicht gut? Mein geräuchertes Fleisch bringt die höchsten Preise. Niemand außer mir bietet die exotischen Geschmackserlebnisse, die es hier in den Hügeln gibt. Und es ist sehr effizient. Ihr geht gegen ein kleines Entgelt auf die Jagd und meine guten Freunde bringen die Bestien hierher, wo sie gehäutet und geräuchert werden!\n\nIch beherrsche den Markt für Frostsäblerfleisch momentan. Unglaublich leckeres Zeug, aus dem man gute Würste machen kann. Zieht los und jagt die Katzen westlich von hier. Das ist ein guter Anfang!", sourceObjective = "Tötet 15 Frostsäbler oder Frostsäblerpirscherinnen.", completion = "Sehr schön! Hört nicht auf, wir haben noch größeres vor!", sourceObjectiveStatus = "unverified-source-field" }
quests[28641] = { id = 28641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzenburger", description = "Also gut, <Kleiner/Kleine>, jetzt geht es weiter nach draußen!\n\nDiese Lieferung war nicht schlecht, aber weiter westlich gibt es wesentlich größere Kätzchen. Die Rudelbehüterinnen und Jägerinnen sind wesentlich muskulöser. Hamburger aus ihrem Fleisch schmecken PHANTASTISCH. Sie verkaufen sich wie verrückt!\n\nGebt mir kurz Bescheid, wenn Ihr fertig seid, dann lassen wir Euch auf den Hauptgang los.", sourceObjective = "Tötet 15 Frostsäblerjägerinnen oder Rudelbehüterinnen der Frostsäbler.", sourceObjectiveStatus = "unverified-source-field" }
quests[28642] = { id = 28642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "Die Großkatzen im Norden von Winterquell versammeln sich an einem auffälligen Punkt, der Frostsäblerfelsen genannt wird. Die Anführerin dieser Katzen heißt Shy-Rotam. Die Matriarchin der Frostsäbler zu besiegen, würde Euch großes Ansehen bei den anderen {race} verschaffen.\n\nGeht noch einmal hinaus in die grausame Wildnis und sammelt heiliges Fleisch von den Frostsäblern. Findet den Stein von Shy-Rotam und legt es dorthin. Wenn Shy-Rotam das Fleisch der ihren sieht, wird sie auftauchen - wutentbrannt.\n\nBereitet Euch auf ihren Zorn vor und besiegt sie.", sourceObjective = "Storm Schattenhuf in Ewige Wacht in Winterquell möchte, dass Ihr Shy-Rotam besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28643] = { id = 28643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: Zephyrus", description = "Burg Durnholde war stets ein Ort des Unfriedens. Jahrelang benutzten die Menschen sie als Internierungslager und Gefängnis für die Orcs. Danach wurde sie vom Syndikat übernommen. Und jetzt? Die Dunkle Fürstin hat mächtige Elementare gefangen und innerhalb ihrer Mauern ausgesetzt. Sie hat mir die Leitung der \"Herausforderung von Durnholde\" übertragen. Wer alle Elementare besiegt, erhält eine große Belohnung! Nehmt dieses Handbuch und stellt Euch Eurer ersten Herausforderung: Zephyrus!\n\nDurnholde liegt nordöstlich von uns.", sourceObjective = "Tötet Zephyrus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28644] = { id = 28644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: Teracula", description = "Das Handbuch benennt Teracula als Eure nächste Herausforderung. Er folgt dem Pfad vor Zephyrus' Versteck.", sourceObjective = "Tötet Teracula.", sourceObjectiveStatus = "unverified-source-field" }
quests[28645] = { id = 28645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: Blutgift", description = "Das Handbuch benennt Blutgift als Eure nächste Herausforderung. Dieser furchterregende Elementar hält sich auf der unteren Ebene der Burg Durnholde, nahe des westlichen Gefängnisses auf.", sourceObjective = "Tötet Blutgift.", sourceObjectiveStatus = "unverified-source-field" }
quests[28646] = { id = 28646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: Infernus", description = "Das Handbuch benennt Infernus als Eure nächste Herausforderung. Diesen Alptraum aus geschmolzener Lava und wütenden Flammen findet Ihr auf der unteren Ebene der Burg Durnholde, nahe des östlichen Gefängnisses.", sourceObjective = "Tötet Infernus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28647] = { id = 28647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: D-1000", description = "Ein Wesen, das aus reinem Quecksilber besteht, wird in der alten Arena der Burg Durnholde gefangen gehalten. Die Verlassenen nennen es den D-1000. Tötet den D-1000 und holt Eure Belohnung ab!", sourceObjective = "Tötet den D-1000.", completion = "Noch nie zuvor hat jemand die Herausforderung abgeschlossen. Ihr seid ein wirklich mächtiger {class}, {name}. Wie versprochen könnt Ihr Euch eine Belohnung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28648] = { id = 28648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fraks wilde Fahrt" }
quests[28649] = { id = 28649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, zerlegten alles und machten uns auf den Weg zum Zellenblock. Wir haben nicht mit dem gerechnet, was wir dort fanden, {name}. Der Kreuzzug hat ganze Arbeit geleistet. Da sitzen jede Menge Gefangene der Argentumdämmerung. Die meisten waren schon tot, als wir eintrafen, aber ein paar haben noch geatmet.\n\nIch wollte den Rest eigentlich selbst hinrichten, aber ich denke, die Ehre gebührt Euch. Vor allem den angriffslustigen Worgen, der dort sitzt, werdet Ihr bestimmt mit großer Freude hinrichten.", sourceObjective = "Ritterkommandant Seuchenfaust bei der Kapelle der Scharlachroten Flamme hat Euch befohlen, den Gefangenen der Argentumdämmerung, Lord Harford, im nahegelegenen Gefängnis hinzurichten.", progress = "Wie fühlt Ihr Euch?", completion = "Das war doch gut, oder? Ihr gehört jetzt nicht mehr zu ihnen, {name}. Ihr seid jetzt bei der Geißel. Ihr seid auf ewig einer von uns...", sourceObjectiveStatus = "unverified-source-field" }
quests[28650] = { id = 28650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Als wir hier ankamen, haben wir alles auseinandergenommen und sind dann zum Gefängnis gezogen. Was wir dort fanden, hatten wir nicht erwartet, {name}. Es scheint, der Kreuzzug war sehr fleißig. Das ganze Ding ist voller Gefangener der Argentumdämmerung. Die meisten waren schon tot, als wir eintrafen, doch ein paar atmeten noch.\n\nIch wollte gerade hingehen und den Rest umbringen, doch ich denke, Ihr solltet die Ehre haben. Es ist ein besonders aufmüpfiger Goblin darunter. Ich glaube, ihn zu richten wird Euch große Freude machen.", sourceObjective = "Ritterkommandant Seuchenfaust bei der Kapelle der Scharlachroten Flamme hat Euch befohlen, den Gefangenen der Argentumdämmerung, Gally Klumpfleck, im nahegelegenen Gefängnis hinzurichten.", completion = "Das war doch gut, oder? Ihr gehört jetzt nicht mehr zu ihnen, {name}. Ihr seid jetzt bei der Geißel. Ihr seid auf ewig einer von uns...", sourceObjectiveStatus = "unverified-source-field" }
quests[28651] = { id = 28651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Novizin Elreth", description = "Geht doch und sprecht mit meiner Novizin Elreth. Sie dient mir und hat wahrscheinlich einige Aufgaben, für die Ihr Eure neu erworbenen Fähigkeiten einsetzen könnt.", sourceObjective = "Sprecht mit Novizin Elreth in Todesend in Tirisfal.", completion = "Möge die Dunkle Fürstin über Euch wachen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28652] = { id = 28652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwalter Caice", description = "Ich brauche Euch nicht mehr. Es gibt jedoch andere, für die Eure Hilfe wichtig ist.\n\nVerwalter Caice auf dem Stumpf hinter mir wird Euch wohl einen Auftrag geben können. Sprecht jetzt mit ihm.", sourceObjective = "Sprecht mit Verwalter Caice an den Gräbern von Todesend in Tirisfal.", completion = "Ja, bitte? Und Ihr seid...?", sourceObjectiveStatus = "unverified-source-field" }
quests[28653] = { id = 28653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenpriester Sarvis", description = "Ihr seid noch immer hier, {name}? Ich bin ja leider nur eine Todeswache und habe kaum Aufgaben, die ich zufälligen Passanten geben kann.\n\nAm besten sprecht Ihr mit Schattenpriester Sarvis. Nachdem sie mich damals aus dem Grab geholt hatten, hat er mich wieder auf die Beine gebracht. Er tut das sicher auch für Euch.\n\nIhr findet ihn in der Kapelle, hier auf der Westseite der Stadt.", sourceObjective = "Sprecht mit Schattenpriester Sarvis in Todesend in Tirisfal.", completion = "Seid gegrüßt, {name}.\n\nWie ich sehe, führt Ihr eine Waffe. Könnt Ihr kämpfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28654] = { id = 28654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Pudels Kern", description = "Ich würd' ja gern noch ein Weilchen bleiben und mit Euch in die Gegend schauen, <Bürschchen/Mädel>.\n\nAlso, ich hab' bestimmt schon die tollsten Dinger gesehn, aber so was ist mir mein Lebtag noch nicht untergekommen.\n\nLeider muss ich diese Scheiben noch gründlicher untersuchen, eh' ich mich zu den Hallen des Ursprungs aufmachen kann.\n\nIch glaub', Ihr seid schwer in Ordnung. Wollt Ihr mal sehen, wie ein richtiger Archäologe arbeitet? Dann kommt mit!", sourceObjective = "Brann Bronzebart möchte, dass Ihr ihn in den Hallen des Ursprungs trefft.", completion = "Höchste Zeit, dass Ihr eintrefft, Bursche.\n\nAuf geht's! An die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[28655] = { id = 28655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Wildhammer-Hochzeit", description = "Wir sind bereit, {name}!\n\nIch weiß aber aus sicherer Quelle, dass der Schattenhammer versuchen wird, die Zeremonie zu vereiteln. Damit soll der Wildhammer demoralisiert und zerstört werden. Es kann gefährlich werden!\n\nDeshalb werde ich die Zeremonie selbst vollziehen und Braut und Bräutigam in nächster Nähe behalten. Klingt das gut? Bestens!\n\nDa Fannys Vater nicht mehr lebt und ihr Bruder Trauzeuge des Bräutigams ist, bittet sie darum, dass Ihr sie an den Altar geleitet. Welch eine Ehre! Gebt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Sagt Grundy MacGraff, dass die Hochzeitszeremonie beginnen kann. Tötet jeden Schattenhammer, der versucht, sie zu verhindern.", completion = "{name}, wir haben's geschafft! Wie alle Wildhämmer zusammen gegen dieses... Ding gekämpft haben - das hat sie so richtig zusammengeschweißt. Die Familienoberhäupter sind so einig wie nie zuvor. Zum Wohl, {name}, lasst uns feiern!!\n\nMit unserer Arbeit stehen wir natürlich noch ganz am Anfang. Ich lasse unsere neue Wildhammerverstärkung zum Rest der Allianz hinzustoßen und den Sturm der Bastion des Zwielichts vorbereiten.\n\nWir treffen uns bestimmt bald wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[28656] = { id = 28656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Lebenskräfte", description = "Beim Tod dieser Kreatur ist ihr eine Art Energie entstiegen. Diese Energie ist auf Euch übergegangen und so fühlt Ihr Euch etwas stärker.\n\nGlaubt man den Einwohnern von Winterquell, dann ist die Hexendoktorin Mau'ari an Schneewehs Berghütte eine Expertin für die Tierwelt dieser Gegend. Vielleicht weiß sie was über die geheimnisvolle Energie.", sourceObjective = "Begebt Euch zu Schneewehs Berghütte in Winterquell und sprecht dort mit Hexendoktorin Mau'ari.", completion = "Was'n das? Du riechst nach E'ko! Lass dir von Mau'ari mal was übers E'ko erzähl'n un' was es so tut.\n\nDu hast Glück, {race}. Das E'ko is' zu dir gekommen. Ein einfacher Troll wie ich muss selber E'ko such'n.\n\nDie Kreaturen von Winterquell hab'n alle E'ko. Die Furbolgs, die Schimären, die Splitterzähne... sogar die Eisdistelyetis! Wenn du so 'ne Kreatur tötest, kommt manchmal 'n bisschen E'ko 'raus. Verschiedene Kreaturen... verschiedenes E'ko.\n\nDann mal los. Such' weiter E'ko!", sourceObjectiveStatus = "unverified-source-field" }
